    // ─────────────── ۳۷: مادام بواری ───────────────
    private fun story37() = StoryContent(
        storyId = "int_madame_bovary_int",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Dreamer", titlePersian = "دختر رؤیایی",
                paragraphs = listOf(
                    StoryParagraph("Emma Rouault was a young woman who had grown up on her father's farm in the quiet countryside of Normandy.", "اِما روئو زن جوانی بود که در مزرعه پدرش در حومه آرام نورماندی بزرگ شده بود."),
                    StoryParagraph("Life on the farm was simple and hard, full of endless chores and the smell of animals and earth.", "زندگی در مزرعه ساده و سخت بود، پر از کارهای بی‌پایان و بوی حیوانات و خاک."),
                    StoryParagraph("But Emma's mind was not on the farm; it was far away, lost in the pages of romantic novels she read secretly in her room.", "اما ذهن اِما در مزرعه نبود؛ دور بود، گم در صفحات رمان‌های عاشقانه‌ای که مخفیانه در اتاقش می‌خواند."),
                    StoryParagraph("She had read countless stories about passionate love, elegant balls, and handsome princes who swept poor girls off their feet.", "او داستان‌های بی‌شماری درباره عشق پرشور، مهمانی‌های باشکوه و شاهزادگان خوش‌قیافه‌ای که دختران فقیر را از پا درمی‌آوردند خوانده بود."),
                    StoryParagraph("In these books, life was always beautiful, always exciting, always full of meaning and sensation.", "در این کتاب‌ها، زندگی همیشه زیبا بود، همیشه هیجان‌انگیز، همیشه پر از معنا و احساس."),
                    StoryParagraph("Emma believed that such a life waited for her somewhere, if only she could escape the tedium of the farm.", "اِما باور داشت چنین زندگی‌ای جایی منتظرش است، اگر فقط می‌توانست از یکنواختی مزرعه فرار کند."),
                    StoryParagraph("She dreamed of a handsome husband who would adore her, and of a grand house filled with silk and silver and music.", "او رویای همسری خوش‌قیافه را داشت که می‌پرستیدش و خانه‌ای باشکوه پر از ابریشم و نقره و موسیقی."),
                    StoryParagraph("She dreamed of beautiful dresses and sparkling jewels and the admiration of everyone she met.", "او رویای لباس‌های زیبا و جواهرات درخشان و تحسین هر کسی که ملاقات می‌کرد را داشت."),
                    StoryParagraph("She dreamed of being rich, of being admired, of being someone.", "او رویای ثروتمند بودن، تحسین‌شده بودن، کسی بودن را داشت."),
                    StoryParagraph("Her father was a simple, practical farmer who did not understand his daughter's fanciful nature.", "پدرش کشاورز ساده و عملی‌ای بود که طبیعت خیال‌پرداز دخترش را درک نمی‌کرد."),
                    StoryParagraph("He only knew that Emma was restless and unhappy, and that she seemed to want something he could not give her.", "او فقط می‌دانست اِما بی‌قرار و ناراضی است و به نظر می‌رسید چیزی می‌خواهد که نمی‌توانست بدهدش."),
                    StoryParagraph("One day, a young country doctor named Charles Bovary came to set her father's broken leg.", "یک روز، دکتر روستایی جوانی به نام شارل بواری برای درمان پای شکسته پدرش آمد."),
                    StoryParagraph("Charles was not a brilliant man; he was slow, kind, and utterly ordinary.", "شارل مرد درخشانی نبود؛ کند، مهربان و کاملاً معمولی بود."),
                    StoryParagraph("He was not handsome, he was not rich, and he had none of the passion or daring that Emma had read about in her books.", "او خوش‌قیافه نبود، ثروتمند نبود و هیچ‌کدام از شور و جسارتی که اِما در کتاب‌هایش خوانده بود را نداشت."),
                    StoryParagraph("But he loved Emma with all the simple, steady love that his plain heart could hold.", "اما اِما را با تمام عشق ساده و پایداری که قلب معمولی‌اش می‌توانست داشته باشد دوست داشت."),
                    StoryParagraph("He had recently lost his first wife, a woman much older than himself, and he was lonely.", "او اخیراً همسر اولش را از دست داده بود، زنی بسیار بزرگ‌تر از خودش، و تنها بود."),
                    StoryParagraph("When he looked at Emma, he saw youth, beauty, and the promise of a happiness he had never known.", "وقتی به اِما نگاه می‌کرد، جوانی، زیبایی و وعده خوشبختی‌ای که هرگز نشناخته بود را می‌دید."),
                    StoryParagraph("When Emma looked at Charles, she saw only a man who was different from her dreams.", "وقتی اِما به شارل نگاه می‌کرد، فقط مردی می‌دید که با رویاهایش متفاوت بود."),
                    StoryParagraph("But she was tired of the farm, tired of her father's silence, tired of the emptiness of her daily life.", "اما او از مزرعه خسته بود، از سکوت پدرش خسته بود، از پوچی زندگی روزانه‌اش خسته بود."),
                    StoryParagraph("So when Charles asked her father for her hand in marriage, she did not refuse.", "بنابراین وقتی شارل از پدرش دستش را برای ازدواج خواست، رد نکرد."),
                    StoryParagraph("Her father agreed readily, pleased that his difficult daughter would finally have a home of her own.", "پدرش با آمادگی موافقت کرد، خوشحال که دختر دشوارش بالاخره خانه‌ای از خودش می‌داشت."),
                    StoryParagraph("Emma believed, or at least tried to believe, that marriage would bring the happiness her books had promised.", "اِما باور داشت، یا حداقل تلاش می‌کرد باور کند، که ازدواج خوشبختی‌ای که کتاب‌هایش وعده داده بودند را می‌آورد."),
                    StoryParagraph("They were married on a cool spring morning in a small village church decorated with modest flowers.", "آن‌ها در صبحی سرد از بهار در کلیسای کوچک دهکده‌ای که با گل‌های ساده تزئین شده بود ازدواج کردند."),
                    StoryParagraph("Emma had dreamed of a grand wedding with musicians and elegant guests.", "اِما رویای عروسی باشکوهی با نوازندگان و مهمانان شیک را در سر داشت."),
                    StoryParagraph("Instead, she got a simple country ceremony with a handful of farmers and a plain meal afterward.", "در عوض، مراسم روستایی سادگی با چند کشاورز و شامی ساده بعدش گرفت."),
                    StoryParagraph("She smiled and said the right words, but inside, she felt a quiet, bitter disappointment.", "او لبخند زد و کلمات درست را گفت، اما در درونش، ناامیدی آرام و تلخی حس کرد."),
                    StoryParagraph("Charles did not notice; he was too happy to see anything but her beautiful face.", "شارل متوجه نشد؛ او آنقدر خوشحال بود که چیزی جز صورت زیبایش نمی‌دید."),
                    StoryParagraph("They moved into a modest house in the town of Tostes, where Charles had his medical practice.", "آن‌ها به خانه‌ای معمولی در شهر توست نقل مکان کردند، جایی که شارل مطبش را داشت."),
                    StoryParagraph("The house was small and ordinary, with cheap furniture and a garden that needed work.", "خانه کوچک و معمولی بود، با مبلمانی ارزان و باغی که به کار نیاز داشت."),
                    StoryParagraph("Emma stood in the doorway on the first evening and looked at her new life.", "اِما عصر روز اول در چارچوب در ایستاد و به زندگی جدیدش نگاه کرد."),
                    StoryParagraph("This was it, she thought; this was the life she had been waiting for.", "این همان بود، فکر کرد؛ این همان زندگی‌ای بود که منتظرش بود."),
                    StoryParagraph("But the house did not feel like a dream; it felt small and dull and duller still as the days went on.", "اما خانه شبیه رویا نبود؛ کوچک و کسل‌کننده حس می‌شد و با گذشت روزها کسل‌کننده‌تر."),
                    StoryParagraph("Charles went to work early and returned late, and when he came home, he talked only of his patients and his meals.", "شارل زود سر کار می‌رفت و دیر برمی‌گشت و وقتی به خانه می‌آمد، فقط از بیمارانش و غذاهایش حرف می‌زد."),
                    StoryParagraph("He did not ask her about her thoughts, her feelings, or the dreams that still burned inside her.", "او از او درباره افکارش، احساساتش، یا رویاهایی که هنوز درونش می‌سوختند نمی‌پرسید."),
                    StoryParagraph("Emma sat alone for hours, looking out of the window at the empty street, wondering what she had done.", "اِما ساعت‌ها تنها می‌نشست، از پنجره به خیابان خالی نگاه می‌کرد و از خود می‌پرسید چه کرده است."),
                    StoryParagraph("She tried to love Charles, and she tried to be content, but her heart was elsewhere.", "تلاش کرد شارل را دوست داشته باشد و تلاش کرد راضی باشد، اما قلبش جای دیگری بود."),
                    StoryParagraph("She wanted passion, adventure, romance, and meaning.", "او شور، ماجراجویی، عاشقانه و معنا می‌خواست."),
                    StoryParagraph("And she wanted them all to arrive immediately, fully formed, without effort.", "و می‌خواست همه‌شان بلافاصله برسند، کاملاً شکل گرفته، بدون تلاش."),
                    StoryParagraph("But life does not work that way, and neither does marriage.", "اما زندگی این‌طور کار نمی‌کند و ازدواج هم همین‌طور."),
                    StoryParagraph("Still, Emma was young, and she did not yet know this.", "با این حال، اِما جوان بود و هنوز این را نمی‌دانست."),
                    StoryParagraph("She believed, in her heart, that somewhere a better life was waiting for her.", "او در قلبش باور داشت جایی زندگی بهتری منتظرش است."),
                    StoryParagraph("And she was determined to find it, no matter what it cost.", "و مصمم بود پیدایش کند، هر چه هزینه داشته باشد."),
                    StoryParagraph("That determination would one day destroy her.", "آن تصمیم روزی نابودش می‌کرد."),
                    StoryParagraph("But for now, she was only a young wife in a small house, dreaming of more.", "اما برای حالا، فقط همسر جوانی در خانه‌ای کوچک بود که رویای بیشتر در سر داشت."),
                    StoryParagraph("The days passed slowly, and Emma grew more and more restless.", "روزها آهسته گذشتند و اِما بی‌قرارتر و بی‌قرارتر شد."),
                    StoryParagraph("She began to spend money she did not have on clothes and decorations for the house.", "شروع کرد به خرج کردن پولی که نداشت برای لباس و تزئین خانه."),
                    StoryParagraph("She hoped that these small luxuries would make her feel like the woman she wanted to be.", "امیدوار بود این تجملات کوچک او را شبیه زنی که می‌خواست باشد حس دهند."),
                    StoryParagraph("But the new dresses did not bring her joy, and the new curtains did not change her life.", "اما لباس‌های جدید برایش شادی نیاوردند و پرده‌های جدید زندگی‌اش را عوض نکردند."),
                    StoryParagraph("She began to grow tired of Charles's simple nature, of his kindness, of his patience.", "او شروع کرد به خسته شدن از طبیعت ساده شارل، از مهربانی‌اش، از صبرش."),
                    StoryParagraph("She wanted a husband who would be a hero, not a country doctor.", "او همسری می‌خواست که قهرمان باشد، نه دکتر روستایی."),
                    StoryParagraph("And then, one autumn, Charles received an invitation to a grand ball at a nearby chateau.", "و بعد، در پاییزی، شارل دعوتنامه‌ای برای مهمانی باشکوهی در عمارت نزدیکی دریافت کرد."),
                    StoryParagraph("A wealthy landowner, the Marquis d'Andervilliers, had invited the local doctors to a great celebration.", "زمینداری ثروتمند، مارکی دو آندرویلیه، پزشکان محلی را به جشنی بزرگ دعوت کرده بود."),
                    StoryParagraph("Emma had never been to such an event, and she did not know what to expect.", "اِما هرگز در چنین رویدادی نبوده بود و نمی‌دانست چه انتظاری داشته باشد."),
                    StoryParagraph("But she knew it was the kind of life she had dreamed of, and she prepared for it as if for a coronation.", "اما می‌دانست همان نوع زندگی‌ای است که در رویاهایش بود و مثل تاج‌گذاری برایش آماده شد."),
                    StoryParagraph("She chose her finest dress and her one pair of elegant shoes.", "بهترین لباسش و تنها جفت کفش شیکش را انتخاب کرد."),
                    StoryParagraph("She had her hair done carefully, and she looked at herself in the mirror with hope.", "موهایش را با دقت آراست و با امید به خودش در آینه نگاه کرد."),
                    StoryParagraph("Perhaps, tonight, everything would change.", "شاید، امشب، همه چیز عوض می‌شد."),
                    StoryParagraph("Perhaps tonight she would enter the world she had been born to enter.", "شاید امشب به دنیایی وارد می‌شد که برای ورود به آن زاده شده بود."),
                    StoryParagraph("They rode to the chateau in a carriage, and when they arrived, Emma's heart began to beat faster.", "با کالسکه به عمارت رفتند و وقتی رسیدند، قلب اِما تندتر تپید."),
                    StoryParagraph("And then, they stepped inside, and she saw the world she had been dreaming of all her life.", "و بعد، وارد شدند و او دنیایی را دید که تمام عمر رؤیایش را در سر داشت."),
                    StoryParagraph("And she knew, in that moment, that she could never be satisfied with anything less.", "و در آن لحظه دانست که هرگز نمی‌تواند به کمتر از آن راضی باشد.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Ball", titlePersian = "مهمانی",
                paragraphs = listOf(
                    StoryParagraph("The chateau of the Marquis d'Andervilliers was a magnificent building lit by hundreds of candles.", "عمارت مارکی دو آندرویلیه ساختمانی باشکوه بود که با صدها شمع روشن شده بود."),
                    StoryParagraph("Its windows glowed like golden eyes in the darkness of the winter night.", "پنجره‌هایش مثل چشمان طلایی در تاریکی شب زمستانی می‌درخشیدند."),
                    StoryParagraph("Carriages lined the road for a mile in both directions, bringing the wealthiest and most fashionable people of the region.", "کالسکه‌ها در هر دو جهت به مدت یک مایل جاده را پر کرده بودند و ثروتمندترین و شیک‌ترین افراد منطقه را می‌آوردند."),
                    StoryParagraph("Emma stepped out of their modest carriage and looked up at the chateau with a mixture of awe and longing.", "اِما از کالسکه ساده‌شان پیاده شد و با آمیزه‌ای از هیبت و اشتیاق به عمارت نگاه کرد."),
                    StoryParagraph("She had never seen anything so grand, so beautiful, so different from the small world she knew.", "او هرگز چیزی اینقدر باشکوه، اینقدر زیبا، اینقدر متفاوت از دنیای کوچکی که می‌شناخت ندیده بود."),
                    StoryParagraph("Inside, the walls were hung with tapestries, the floors were marble, and the ceilings were covered in paintings of gods and heroes.", "در داخل، دیوارها با گلیم‌های دیواری پوشیده شده بودند، کف‌ها مرمرین، و سقف‌ها با نقاشی خدایان و قهرمانان پوشیده شده بودند."),
                    StoryParagraph("Chandeliers of crystal hung from the ceilings, spreading soft golden light through every room.", "لوسترهای کریستالی از سقف آویزان بودند و نوری طلایی و ملایم در هر اتاق پخش می‌کردند."),
                    StoryParagraph("The guests were dressed in silks and velvets, in furs and feathers, in every luxury the age could offer.", "مهمانان در ابریشم و مخمل، در خز و پر، در هر تجملی که عصر می‌توانست ارائه دهد لباس پوشیده بودند."),
                    StoryParagraph("The air was thick with the scent of perfume and the sound of elegant music from a hidden orchestra.", "هوا از بوی عطر و صدای موسیقی شیکی که از ارکستری پنهان می‌آمد غلیظ بود."),
                    StoryParagraph("Emma felt as if she had stepped into one of her books, into a world where everything was beautiful and nothing was ordinary.", "اِما حس کرد وارد یکی از کتاب‌هایش شده، به دنیایی که در آن همه چیز زیبا بود و هیچ چیز معمولی نبود."),
                    StoryParagraph("She stood at the edge of the ballroom, watching the dancers, her heart beating with a strange mixture of wonder and sadness.", "او در لبه سالن رقص ایستاد و رقصندگان را تماشا کرد و قلبش با آمیزه عجیبی از شگفتی و اندوه می‌تپید."),
                    StoryParagraph("Everyone moved with a grace and confidence that she had never seen in the people of her own town.", "همه با لطف و اطمینانی حرکت می‌کردند که او هرگز در مردم شهر خودش ندیده بود."),
                    StoryParagraph("They laughed easily, spoke easily, and seemed to belong to the world as if by right.", "راحت می‌خندیدند، راحت صحبت می‌کردند و به نظر می‌رسید به دنیا تعلق دارند، گویی به حق."),
                    StoryParagraph("Charles noticed her looking and said, cheerfully, 'You should dance, my dear. It would do you good.'", "شارل متوجه نگاهش شد و با شادابی گفت: «باید برقصی، عزیزم. برایت خوب می‌شود.»"),
                    StoryParagraph("Emma wanted to dance more than anything, but she was afraid of looking foolish.", "اِما بیش از هر چیزی می‌خواست برقصد، اما می‌ترسید احمق به نظر برسد."),
                    StoryParagraph("She had never learned the elegant dances that the guests performed so effortlessly.", "او هرگز رقص‌های شیکی که مهمانان با چنین بی‌زحمتی اجرا می‌کردند را یاد نگرفته بود."),
                    StoryParagraph("But then, a tall, handsome man with dark hair and a confident smile approached her.", "اما بعد، مردی بلندقد و خوش‌قیافه با موهای تیره و لبخندی مطمئن به طرفش آمد."),
                    StoryParagraph("He was a viscount, the perfect gentleman, and he asked her to dance the next waltz.", "او ویکنت بود، نجیب‌زاده‌ای کامل، و از او خواست والس بعدی را برقصند."),
                    StoryParagraph("Emma felt herself blush, but she could not refuse; something in his eyes told her that this was the moment she had been waiting for.", "اِما حس کرد سرخ شده، اما نمی‌توانست رد کند؛ چیزی در چشمانش به او می‌گفت این همان لحظه‌ای است که منتظرش بود."),
                    StoryParagraph("They danced together across the great marble floor, and Emma forgot everything else in the world.", "آن‌ها با هم روی کف مرمرین بزرگ رقصیدند و اِما هر چیز دیگری در دنیا را فراموش کرد."),
                    StoryParagraph("She forgot the small house, the boring evenings, the husband who did not understand her.", "خانه کوچک را فراموش کرد، شب‌های خسته‌کننده را، شوهری که درکش نمی‌کرد."),
                    StoryParagraph("She forgot her restlessness, her dissatisfaction, her secret sorrow.", "بی‌قراری‌اش را فراموش کرد، نارضایتی‌اش را، اندوه پنهانش را."),
                    StoryParagraph("She was, for a few minutes, the woman she had always wanted to be.", "او، برای چند دقیقه، زنی بود که همیشه می‌خواست باشد."),
                    StoryParagraph("After the dance, the viscount led her to a quiet alcove and poured her a glass of champagne.", "بعد از رقص، ویکنت او را به گوشه‌ای آرام برد و لیوانی شامپاین برایش ریخت."),
                    StoryParagraph("They talked, and he was charming, intelligent, and attentive to every word she said.", "آن‌ها صحبت کردند و او جذاب، باهوش و به هر کلمه‌ای که می‌گفت توجه بود."),
                    StoryParagraph("He seemed to find her fascinating, and Emma's heart swelled with a joy she had not felt in years.", "به نظر می‌رسید او را جذاب می‌یافت و قلب اِما از شادی‌ای که سال‌ها حس نکرده بود پر شد."),
                    StoryParagraph("This, she thought, was what life was supposed to be like.", "این، فکر کرد، همان چیزی بود که زندگی باید مثلش باشد."),
                    StoryParagraph("Not the dull routine of a country doctor's wife, but this: elegance, admiration, and romance.", "نه روال یکنواخت همسر یک دکتر روستایی، بلکه این: ظرافت، تحسین و عاشقانه."),
                    StoryParagraph("She stayed by his side as long as she could, and when he finally said goodbye, she felt as if she were losing something precious.", "تا جایی که می‌توانست کنارش ماند و وقتی بالاخره خداحافظی کرد، حس کرد چیزی باارزش را از دست می‌دهد."),
                    StoryParagraph("The night passed like a dream, and too soon, the musicians played the last dance.", "شب مثل رویایی گذشت و خیلی زود، نوازندگان آخرین رقص را نواختند."),
                    StoryParagraph("Charles was tipsy and sleepy, and he stumbled as he helped her into their carriage.", "شارل سرخوش و خواب‌آلود بود و تلپ خورد همان‌طور که کمکش کرد سوار کالسکه‌شان شود."),
                    StoryParagraph("The carriage pulled away from the chateau, and Emma watched its lights grow smaller and smaller behind her.", "کالسکه از عمارت دور شد و اِما تماشا کرد که نورهایش پشت سرش کوچک‌تر و کوچک‌تر می‌شوند."),
                    StoryParagraph("By the time they reached their own house, the magic was gone.", "تا وقتی به خانه خودشان رسیدند، جادو رفته بود."),
                    StoryParagraph("The house looked small and shabby in the grey light of morning.", "خانه در نور خاکستری صبح کوچک و فرسوده به نظر می‌رسید."),
                    StoryParagraph("The furniture looked cheap; the curtains looked faded; even the garden looked ugly.", "مبلمان ارزان به نظر می‌رسید؛ پرده‌ها رنگ‌پریده؛ حتی باغ زشت به نظر می‌رسید."),
                    StoryParagraph("Emma went to her room, closed the door, and sat down on the edge of the bed.", "اِما به اتاقش رفت، در را بست و روی لبه تخت نشست."),
                    StoryParagraph("She did not cry, because she had no tears left; she only sat there, staring at the wall, feeling utterly and completely lost.", "گریه نکرد، چون اشکی برایش نمانده بود؛ فقط همان‌جا نشست و به دیوار خیره شد و کاملاً و مطلقاً گمشده حس کرد."),
                    StoryParagraph("After that night, nothing in her life seemed worth anything.", "بعد از آن شب، هیچ چیز در زندگی‌اش ارزشمند به نظر نمی‌رسید."),
                    StoryParagraph("The farm, the town, the house, the husband, the people she saw every day—all of it felt like a prison.", "مزرعه، شهر، خانه، شوهر، افرادی که هر روز می‌دید—همه‌شان مثل زندانی حس می‌شدند."),
                    StoryParagraph("And yet she could not escape, because she did not know how.", "و با این حال نمی‌توانست فرار کند، چون نمی‌دانست چطور."),
                    StoryParagraph("She had no money of her own, no skills, no way to support herself.", "پول خودش را نداشت، مهارتی نداشت، راهی برای حمایت از خودش نداشت."),
                    StoryParagraph("She was trapped, and she knew it, and the knowledge began to poison her soul.", "او گرفتار بود، و می‌دانست، و این آگاهی شروع کرد به مسموم کردن روحش."),
                    StoryParagraph("She grew colder toward Charles, and he, confused and hurt, did not know how to reach her.", "او با شارل سردتر شد و او، گیج و زخمی، نمی‌دانست چطور به او برسد."),
                    StoryParagraph("She stopped talking to him about anything that mattered.", "او از صحبت با او درباره هر چیز مهمی دست کشید."),
                    StoryParagraph("She spent hours alone in her room, dreaming of the ball, of the viscount, of a life she could never have.", "او ساعت‌ها تنهای تنها در اتاقش می‌گذراند و رویای مهمانی، رویای ویکنت، رویای زندگی‌ای را می‌دید که هرگز نمی‌توانست داشته باشد."),
                    StoryParagraph("Her beauty, which had once been fresh and lively, now began to fade into a cold, distant elegance.", "زیبایی‌اش که زمانی تازه و زنده بود، حالا شروع کرد به محو شدن به ظرافتی سرد و دور."),
                    StoryParagraph("Her eyes grew hard; her mouth grew tight; her laughter disappeared.", "چشمانش سخت شد؛ دهانش تنگ شد؛ خنده‌اش ناپدید شد."),
                    StoryParagraph("And Charles, poor Charles, did not understand any of it.", "و شارل، بیچاره شارل، هیچ‌کدام از این‌ها را نمی‌فهمید."),
                    StoryParagraph("He only knew that the woman he loved was slipping away from him.", "او فقط می‌دانست زنی که دوست داشت داشت از او دور می‌شد."),
                    StoryParagraph("He tried to please her, but every effort made things worse.", "تلاش کرد خوشحالش کند، اما هر تلاشی بدترش می‌کرد."),
                    StoryParagraph("The chasm between them widened, month by month, and neither of them knew how to bridge it.", "شکاف میانشان ماه‌به‌ماه پهن‌تر می‌شد و هیچ‌کدام نمی‌دانستند چطور پرش کنند."),
                    StoryParagraph("And then, one day, fate offered Emma a chance at the life she had been dreaming of.", "و بعد، یک روز، تقدیر فرصتی از زندگی‌ای که رؤیایش را در سر داشت به اِما پیشنهاد داد."),
                    StoryParagraph("And she took it without hesitation.", "و او بدون تردید پذیرفتش."),
                    StoryParagraph("But it would not lead where she hoped.", "اما به جایی که امید داشت نمی‌رسید."),
                    StoryParagraph("It would lead to her destruction.", "به نابودی‌اش می‌رسید.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Lovers", titlePersian = "عاشقان",
                paragraphs = listOf(
                    StoryParagraph("A few months after the ball, Charles and Emma moved to a larger town called Yonville, hoping a change of scene might help his struggling practice.", "چند ماه بعد از مهمانی، شارل و اِما به شهر بزرگتری به نام یونویل نقل مکان کردند، به امید اینکه تغییر منظره به مطب در حال تقلای شارل کمک کند."),
                    StoryParagraph("Emma was pregnant with their first child, and for a while, the coming baby gave her something to look forward to.", "اِما باردار اولین فرزندشان بود و برای مدتی، بچه‌ای که در راه بود چیزی به او داد که منتظرش باشد."),
                    StoryParagraph("But the baby, a girl named Berthe, did not bring her the joy she had expected.", "اما بچه، دختری به نام برت، شادی‌ای که انتظارش را داشت برایش نیاورد."),
                    StoryParagraph("Emma was not a natural mother; she found the child dull and the duties of motherhood tedious.", "اِما مادر طبیعی نبود؛ بچه را کسل‌کننده و وظایف مادری را یکنواخت می‌یافت."),
                    StoryParagraph("She sent the baby to be nursed by a wet nurse in the village and returned to her old habits of daydreaming and dissatisfaction.", "بچه را برای شیردهی به دایه‌ای در دهکده فرستاد و به عادت‌های قدیمی‌اش در خیال‌پردازی و نارضایتی برگشت."),
                    StoryParagraph("In Yonville, she met a young law clerk named Léon Dupuis, who boarded at the same inn where she often took her meals.", "در یونویل، او دبیری جوان به نام لئون دوپوی را ملاقات کرد که در همان مهمانخانه‌ای که او اغلب غذایش را می‌خورد اقامت داشت."),
                    StoryParagraph("Léon was romantic, well-read, and just as dreamy and restless as Emma herself.", "لئون رمانتیک، خوش‌مطالعه و به‌اندازه خود اِما خیال‌پرداز و بی‌قرار بود."),
                    StoryParagraph("He loved poetry, art, and long conversations about everything beautiful and melancholy in life.", "او عاشق شعر، هنر و مکالمات طولانی درباره هر چیزی زیبا و مالیخولیایی در زندگی بود."),
                    StoryParagraph("He found Emma fascinating, and Emma found in him the kind of man she had always imagined she would love.", "او اِما را جذاب می‌یافت و اِما در او همان نوع مردی را می‌یافت که همیشه تصور می‌کرد دوستش خواهد داشت."),
                    StoryParagraph("They began to spend time together, walking in the garden, talking until late at night, reading poetry in the fading light.", "آن‌ها شروع کردند به گذراندن وقت با هم، قدم زدن در باغ، صحبت کردن تا دیروقت، خواندن شعر در نور محو."),
                    StoryParagraph("There was a strong attraction between them, and both of them knew it, but neither had the courage to speak.", "جذابیت شدیدی بین آن‌ها بود و هر دو می‌دانستند، اما هیچ‌کدام جرات حرف زدن نداشتند."),
                    StoryParagraph("Emma was married, and Léon was too shy and too principled to make a move.", "اِما متأهل بود و لئون بیش از حد خجالتی و بیش از حد اصول‌گرا بود که اقدامی کند."),
                    StoryParagraph("But their hearts spoke to each other in every glance, every touch of the hand, every hesitation.", "اما قلب‌هایشان در هر نگاه، هر لمس دست، هر تردید با هم صحبت می‌کردند."),
                    StoryParagraph("Then, one day, Léon announced that he was leaving Yonville to study law in Paris.", "بعد، یک روز، لئون اعلام کرد که یونویل را برای تحصیل حقوق در پاریس ترک می‌کند."),
                    StoryParagraph("He said goodbye to Emma in the garden, and his eyes were full of everything he had never dared to say.", "او در باغ با اِما خداحافظی کرد و چشمانش پر از هر چیزی بود که هرگز جرات نکرده بود بگوید."),
                    StoryParagraph("Emma watched him go, and then she went to her room and wept.", "اِما رفتنش را تماشا کرد و بعد به اتاقش رفت و گریه کرد."),
                    StoryParagraph("She wept for what might have been, for what she had lost, for what she had never had.", "او برای آنچه می‌توانست باشد گریه کرد، برای آنچه از دست داده بود، برای آنچه هرگز نداشته بود."),
                    StoryParagraph("For weeks afterward, she was silent and pale, and Charles, worried, could not understand why.", "هفته‌ها بعد ساکت و رنگ‌پریده بود و شارل، نگران، نمی‌فهمید چرا."),
                    StoryParagraph("Then, into this despair, walked a man who would change everything.", "سپس، به این ناامیدی، مردی وارد شد که همه چیز را عوض می‌کرد."),
                    StoryParagraph("His name was Rodolphe Boulanger, and he was the wealthy owner of a nearby estate.", "نامش رودولف بولانژه بود و صاحب ثروتمند ملکی در همان نزدیکی بود."),
                    StoryParagraph("He was handsome, confident, experienced with women, and utterly without conscience.", "او خوش‌قیافه، مطمئن، باتجربه با زنان و کاملاً بی‌وجدان بود."),
                    StoryParagraph("He had seen Emma at a fair, and he had decided that he wanted her.", "او اِما را در نمایشگاهی دیده بود و تصمیم گرفته بود می‌خواهدش."),
                    StoryParagraph("He was not in love with her; he merely found her beautiful and desirable, and he was used to getting what he wanted.", "او عاشقش نبود؛ فقط زیبا و مطلوب می‌یافتش و به گرفتن آنچه می‌خواست عادت داشت."),
                    StoryParagraph("He began to court her with all the skill of a man who had done this many times before.", "او شروع کرد به خواستگاری‌اش با تمام مهارت مردی که این کار را بارها کرده بود."),
                    StoryParagraph("He arranged to meet her alone, he flattered her, he spoke of passion and destiny and the cruelty of fate.", "او ترتیبی داد که تنها ملاقاتش کند، چاپلوسی‌اش کرد، از شور و سرنوشت و ظلم تقدیر گفت."),
                    StoryParagraph("He said the words that Emma had been waiting her whole life to hear.", "او کلماتی گفت که اِما تمام عمر منتظر شنیدنشان بود."),
                    StoryParagraph("Emma, starved for affection and desperate for romance, fell for him completely.", "اِما که از محبت محروم و ناامید از عاشقانه بود، کاملاً به او دل داد."),
                    StoryParagraph("She believed that Rodolphe truly loved her, and she began to dream of a life with him.", "او باور داشت رودولف واقعاً دوستش دارد و شروع کرد به رویای زندگی‌ای با او."),
                    StoryParagraph("They met secretly in the woods, in the garden, in her own house when Charles was away.", "آن‌ها مخفیانه در جنگل، در باغ، در خانه خودش وقتی شارل نبود ملاقات می‌کردند."),
                    StoryParagraph("Emma had never been so happy.", "اِما هرگز اینقدر خوشحال نبوده بود."),
                    StoryParagraph("She had finally found the passion, the excitement, the romance that she had been seeking all her life.", "او بالاخره شور، هیجان، عاشقانه‌ای که تمام عمر در جست‌وجویش بود را یافته بود."),
                    StoryParagraph("She gave herself to Rodolphe without reservation, without caution, without thought of the consequences.", "او خودش را بدون قید و شرط به رودولف داد، بدون احتیاط، بدون فکر کردن به عواقب."),
                    StoryParagraph("She believed they would run away together and live happily forever.", "باور داشت با هم فرار می‌کنند و برای همیشه خوشحال زندگی می‌کنند."),
                    StoryParagraph("She began to plan the escape: she would leave Charles, she would take Berthe, she would go to Italy with Rodolphe.", "شروع کرد به نقشه کشیدن فرار: شارل را ترک می‌کرد، برت را می‌برد، با رودولف به ایتالیا می‌رفت."),
                    StoryParagraph("She spoke of this constantly, and Rodolphe nodded and smiled and said all the right things.", "او مدام از این حرف می‌زد و رودولف سر تکان می‌داد و لبخند می‌زد و همه چیزهای درست را می‌گفت."),
                    StoryParagraph("But Rodolphe had no intention of running away with anyone.", "اما رودولف قصد فرار با هیچ‌کس را نداشت."),
                    StoryParagraph("He was a confirmed bachelor, a man who loved his freedom and his estates and his comfortable life.", "او مجردی سرسخت بود، مردی که آزادی‌اش و ملک‌هایش و زندگی راحتش را دوست داشت."),
                    StoryParagraph("When Emma's demands became too insistent, he began to grow tired of her.", "وقتی خواسته‌های اِما خیلی اصرارآمیز شد، شروع کرد به خسته شدن از او."),
                    StoryParagraph("When she spoke of leaving Charles, he began to feel trapped.", "وقتی از ترک شارل صحبت کرد، شروع کرد به حس گرفتار بودن."),
                    StoryParagraph("When she cried and clung to him, he began to feel irritated.", "وقتی گریه می‌کرد و به او می‌چسبید، شروع کرد به حس آزردگی کردن."),
                    StoryParagraph("He decided that he had to end things before they got out of hand.", "تصمیم گرفت باید قبل از اینکه از کنترل خارج شوند، تمامشان کند."),
                    StoryParagraph("So one morning, before dawn, he wrote Emma a letter.", "بنابراین یک صبح، پیش از سپیده‌دم، نامه‌ای برای اِما نوشت."),
                    StoryParagraph("In the letter, he said that he loved her but that he had to leave her.", "در نامه گفت که دوستش دارد اما باید ترکش کند."),
                    StoryParagraph("He said that fate was cruel and that they could never be together.", "گفت تقدیر ظالم است و هرگز نمی‌توانند با هم باشند."),
                    StoryParagraph("He said that he was leaving for a long journey and that she should forget him.", "گفت برای سفری طولانی می‌رود و باید فراموشش کند."),
                    StoryParagraph("He placed the letter in a basket of apricots and had it delivered to her house.", "نامه را در سبدی از زردآلو گذاشت و به خانه‌اش فرستاد."),
                    StoryParagraph("Then he climbed into his carriage and drove away.", "بعد سوار کالسکه‌اش شد و رفت."),
                    StoryParagraph("Emma read the letter in the garden and felt the world collapse around her.", "اِما نامه را در باغ خواند و حس کرد دنیا دورش فرو می‌ریزد."),
                    StoryParagraph("She did not scream; she did not cry; she simply walked, slowly and mechanically, back to the house.", "جیغ نزد؛ گریه نکرد؛ فقط آهسته و مکانیکی به خانه برگشت."),
                    StoryParagraph("She climbed to the attic and opened the window and looked down at the street below.", "به اتاق زیرشیروانی رفت و پنجره را باز کرد و به خیابان پایین نگاه کرد."),
                    StoryParagraph("For a long moment, she considered jumping, ending everything, escaping the pain.", "لحظه‌ای طولانی، به پریدن فکر کرد، به پایان دادن به همه چیز، به فرار از درد."),
                    StoryParagraph("But then she heard Charles calling her name from below, and she stepped back from the window.", "اما بعد شنید شارل از پایین نامش را صدا می‌زند و از پنجره عقب کشید."),
                    StoryParagraph("She collapsed onto the floor and wept until she could weep no more.", "روی زمین فرو ریخت و گریه کرد تا نتوانست بیشتر گریه کند."),
                    StoryParagraph("When she finally stood up, something inside her had changed forever.", "وقتی بالاخره بلند شد، چیزی در درونش برای همیشه عوض شده بود."),
                    StoryParagraph("She was no longer the innocent dreamer who had come to Yonville.", "او دیگر رؤیاپرداز بی‌گناهی که به یونویل آمده بود نبود."),
                    StoryParagraph("She was a woman who had loved and lost, and who would never trust anyone again.", "او زنی بود که عشق ورزیده و از دست داده بود و دیگر هرگز به کسی اعتماد نمی‌کرد."),
                    StoryParagraph("She did not know it yet, but she was also a woman who was falling.", "هنوز نمی‌دانست، اما او زنی بود که در حال سقوط بود."),
                    StoryParagraph("And the fall would be long and terrible, and it would end in death.", "و سقوط طولانی و هولناک می‌بود و به مرگ ختم می‌شد."),
                    StoryParagraph("But not yet.", "اما نه هنوز."),
                    StoryParagraph("There were still many chapters of suffering and ruin to be written.", "هنوز فصل‌های زیادی از رنج و تباهی باقی بود که نوشته شود.")
                )
            ),
            StoryChapter(
                number = 4, title = "The Fall", titlePersian = "سقوط",
                paragraphs = listOf(
                    StoryParagraph("After Rodolphe abandoned her, Emma became very ill.", "بعد از اینکه رودولف رهایش کرد، اِما خیلی مریض شد."),
                    StoryParagraph("She lay in bed for weeks, feverish and silent, refusing to eat, refusing to speak.", "هفته‌ها در تخت دراز کشید، تب‌دار و ساکت، از خوردن امتناع می‌کرد، از صحبت کردن امتناع می‌کرد."),
                    StoryParagraph("Charles was terrified that he would lose her; he stayed by her bedside day and night.", "شارل از ترس اینکه از دستش بدهد وحشت کرده بود؛ شبانه‌روز کنار تختش ماند."),
                    StoryParagraph("He nursed her patiently, tenderly, with a devotion that she neither noticed nor appreciated.", "او با صبر، مهربانی و فداکاری‌ای که اِما نه متوجهش می‌شد و نه قدرش را می‌دانست از او مراقبت کرد."),
                    StoryParagraph("The town's pharmacist, a busybody named Homais, also visited her often and offered his opinion on everything.", "داروساز شهر، فضولی به نام هومه، هم اغلب به دیدنش می‌رفت و نظر خودش را درباره همه چیز ارائه می‌داد."),
                    StoryParagraph("He suggested that a change of scene might help her recover, and Charles, always willing to try anything, agreed.", "او پیشنهاد کرد تغییر منظره ممکن است به بهبودش کمک کند و شارل، همیشه آماده امتحان کردن هر چیزی، موافقت کرد."),
                    StoryParagraph("He decided to take her to the opera in the city of Rouen, hoping the music and the crowds would lift her spirits.", "او تصمیم گرفت او را به اپرا در شهر روئن ببرد، به امید اینکه موسیقی و جمعیت روحیه‌اش را بالا ببرد."),
                    StoryParagraph("At the opera, Emma saw a familiar face.", "در اپرا، اِما چهره آشنایی دید."),
                    StoryParagraph("It was Léon Dupuis, the young law clerk who had loved her silently in Yonville.", "لئون دوپوی بود، دبیر جوان حقوقی که در یونویل بی‌صدا دوستش داشت."),
                    StoryParagraph("He was now living in Rouen, working as a lawyer, and he was more handsome and more confident than ever.", "او حالا در روئن زندگی می‌کرد، به عنوان وکیل کار می‌کرد و از هر زمان دیگری خوش‌قیافه‌تر و مطمئن‌تر بود."),
                    StoryParagraph("They recognized each other immediately, and the old attraction, which had never truly died, flared back to life.", "بلافاصله یکدیگر را شناختند و جذابیت قدیمی که هرگز واقعاً نمرده بود، دوباره شعله‌ور شد."),
                    StoryParagraph("After the opera, Léon came to find her, and they talked for hours.", "بعد از اپرا، لئون به دیدنش آمد و ساعت‌ها صحبت کردند."),
                    StoryParagraph("He was no longer the shy boy she had known; he had learned how to flirt, how to charm, how to pursue what he wanted.", "او دیگر پسر خجالتی‌ای که می‌شناخت نبود؛ یاد گرفته بود چطور لاس بزند، چطور جذاب باشد، چطور دنبال چیزی که می‌خواهد برود."),
                    StoryParagraph("They began to meet in secret every week, when Emma went to Rouen for her piano lessons.", "آن‌ها شروع کردند به ملاقات مخفیانه هر هفته، وقتی اِما برای درس‌های پیانویش به روئن می‌رفت."),
                    StoryParagraph("They met in hotels, in gardens, in cafes; they wrote each other passionate letters; they lived in a dream that they both knew could not last.", "در هتل‌ها، باغ‌ها، کافه‌ها ملاقات می‌کردند؛ برای همدیگر نامه‌های پرشور می‌نوشتند؛ در رؤیایی زندگی می‌کردند که هر دو می‌دانستند نمی‌تواند دوام بیاورد."),
                    StoryParagraph("But Emma, as always, wanted more.", "اما اِما، مثل همیشه، بیشتر می‌خواست."),
                    StoryParagraph("She wanted Léon to marry her, to take her away from Charles, to give her the life she had always dreamed of.", "می‌خواست لئون با او ازدواج کند، او را از شارل دور کند، زندگی‌ای که همیشه رؤیایش را در سر داشت به او بدهد."),
                    StoryParagraph("But Léon, like Rodolphe before him, was not willing to make such a commitment.", "اما لئون، مثل رودولف قبل از خودش، حاضر به چنین تعهدی نبود."),
                    StoryParagraph("He loved Emma, in his own way, but he was not willing to destroy his career or his reputation for her.", "او اِما را به شیوه خودش دوست داشت، اما حاضر نبود حرفه‌اش یا آبرویش را برایش نابود کند."),
                    StoryParagraph("He began to avoid her, to postpone their meetings, to grow cold.", "او شروع کرد به دوری از او، به به تعویق انداختن ملاقات‌هایشان، به سرد شدن."),
                    StoryParagraph("And Emma, watching her dream crumble for a second time, fell into a deep and desperate despair.", "و اِما، در حالی که می‌دید رویایش برای بار دوم فرو می‌ریزد، به ناامیدی عمیق و ناامیدانه‌ای فرو رفت."),
                    StoryParagraph("It was during this period that she began to spend money recklessly.", "در همین دوره بود که شروع کرد به خرج کردن پول به‌طور بی‌پروا."),
                    StoryParagraph("She bought new dresses, new shoes, new hats, new furniture for the house.", "لباس‌های جدید، کفش‌های جدید، کلاه‌های جدید، مبلمان جدید برای خانه خرید."),
                    StoryParagraph("She hired carriages, she ordered meals in expensive restaurants, she showered gifts on Léon.", "کالسکه کرایه می‌کرد، غذا در رستوران‌های گران سفارش می‌داد، هدیه روی هدیه برای لئون می‌ریخت."),
                    StoryParagraph("To pay for all this, she borrowed money from a cunning merchant named Lheureux.", "برای پرداخت همه این‌ها، از تاجری حیله‌گر به نام لورو پول قرض کرد."),
                    StoryParagraph("Lheureux was only too happy to lend her money, because he knew that she could not possibly repay it.", "لورو بیش از حد خوشحال بود پول قرضش دهد، چون می‌دانست او هرگز نمی‌تواند پسش دهد."),
                    StoryParagraph("He charged her enormous interest and demanded promises of payment that he knew she could not keep.", "او بهره‌های عظیمی ازش می‌گرفت و وعده‌های پرداختی ازش می‌خواست که می‌دانست نمی‌تواند نگهشان دارد."),
                    StoryParagraph("Emma signed every paper he put before her, too desperate for money to read or think.", "اِما هر کاغذی که جلویش می‌گذاشت امضا می‌کرد، آنقدر ناامید برای پول که نخواند یا فکر کند."),
                    StoryParagraph("She believed that somehow, some way, everything would work out.", "باور داشت به نحوی، به شکلی، همه چیز درست می‌شود."),
                    StoryParagraph("She believed that she would find the money to pay her debts, that Léon would finally marry her, that happiness was just around the corner.", "باور داشت پولی برای پرداخت بدهی‌هایش پیدا می‌کند، لئون بالاخره با او ازدواج می‌کند، خوشبختی همین نزدیکی است."),
                    StoryParagraph("But the debts kept growing, the money kept disappearing, and Léon kept growing colder.", "اما بدهی‌ها بزرگ‌تر می‌شدند، پول محو می‌شد و لئون سردتر می‌شد."),
                    StoryParagraph("Then one day, Lheureux came to her with a legal document.", "بعد یک روز، لورو با سند قانونی به سراغش آمد."),
                    StoryParagraph("He told her that if she did not pay her debts immediately, he would take everything she owned.", "به او گفت اگر بدهی‌هایش را فوراً نپردازد، هر چیزی که دارد را می‌گیرد."),
                    StoryParagraph("He would take the furniture, the house, the very clothes from her back.", "مبلمان را می‌گرفت، خانه را، حتی لباس‌های تنش را."),
                    StoryParagraph("Emma was terrified; she begged him for more time.", "اِما وحشت کرد؛ التماس کرد زمان بیشتری به او بدهد."),
                    StoryParagraph("He gave her twenty-four hours, and then he left.", "او بیست و چهار ساعت به او داد و بعد رفت."),
                    StoryParagraph("Emma rushed to find Léon, hoping he would help her.", "اِما به دنبال لئون دوید، به امید اینکه کمکش کند."),
                    StoryParagraph("But Léon, frightened by her desperation, made excuses and slipped away.", "اما لئون که از ناامیدی‌اش ترسیده بود، بهانه آورد و فرار کرد."),
                    StoryParagraph("Emma then rushed to Rodolphe, hoping that the old love might save her.", "اِما بعد به دنبال رودولف دوید، به امید اینکه عشق قدیمی نجاتش دهد."),
                    StoryParagraph("But Rodolphe, seeing her come, knew exactly what she wanted, and he refused to help.", "اما رودولف که دیده بودش بیاید، دقیقاً می‌دانست چه می‌خواهد و از کمک امتناع کرد."),
                    StoryParagraph("He told her that he had no money to give her, which was a lie.", "به او گفت پولی برای دادنش ندارد، که دروغ بود."),
                    StoryParagraph("Emma left his house in a state of complete despair.", "اِما خانه‌اش را در وضعیت ناامیدی کامل ترک کرد."),
                    StoryParagraph("She had been rejected by every man she had ever loved.", "هر مردی که دوست داشت ردش کرده بود."),
                    StoryParagraph("She had lost her reputation, her hope, her dreams, and now she was about to lose everything she owned.", "آبرویش، امیدش، رویاهایش را از دست داده بود و حالا در شرف از دست دادن هر چیزی که داشت بود."),
                    StoryParagraph("She walked through the streets of the town in a daze.", "او گیج در خیابان‌های شهر قدم زد."),
                    StoryParagraph("She passed the church, the square, the house where she had lived.", "از کلیسا گذشت، از میدان، از خانه‌ای که در آن زندگی کرده بود."),
                    StoryParagraph("She thought about her life, about her choices, about all the dreams that had turned to dust.", "به زندگی‌اش فکر کرد، به انتخاب‌هایش، به تمام رویاهایی که به خاک تبدیل شده بودند."),
                    StoryParagraph("And she decided that she could not go on.", "و تصمیم گرفت که نمی‌تواند ادامه دهد."),
                    StoryParagraph("She went to the pharmacy when Homais was away, and she found the key to the cabinet where the poisons were kept.", "وقتی هومه نبود به داروخانه رفت و کلید کابینتی که سموم در آن نگه داشته می‌شد را پیدا کرد."),
                    StoryParagraph("She took a handful of white powder, and she went home, and she wrote a letter.", "او مشتی پودر سفید برداشت و به خانه رفت و نامه‌ای نوشت."),
                    StoryParagraph("Then she swallowed the poison.", "بعد سم را بلعید."),
                    StoryParagraph("The pain began within minutes; it was terrible, unbearable, unending.", "درد در عرض چند دقیقه شروع شد؛ هولناک بود، غیرقابل تحمل، بی‌پایان."),
                    StoryParagraph("Charles came home to find her writhing on the bed, crying out, screaming.", "شارل به خانه آمد و او را یافت که روی تخت می‌پیچید، فریاد می‌زد، جیغ می‌کشید."),
                    StoryParagraph("He called for doctors, for help, for anyone.", "او دنبال دکترها دوید، دنبال کمک، دنبال هر کسی."),
                    StoryParagraph("But there was nothing anyone could do.", "اما هیچ‌کس کاری نمی‌توانست بکند."),
                    StoryParagraph("Emma died in agony the next day, without a single word of comfort.", "اِما روز بعد در عذاب مرد، بدون یک کلمه تسلی."),
                    StoryParagraph("Charles was destroyed by her death.", "شارل از مرگش نابود شد."),
                    StoryParagraph("He could not eat; he could not sleep; he could not work.", "نمی‌توانست بخورد؛ نمی‌توانست بخوابد؛ نمی‌توانست کار کند."),
                    StoryParagraph("He kept her room exactly as it had been, and he sat in it for hours, weeping.", "اتاقش را دقیقاً همان‌طور که بود نگه داشت و ساعت‌ها در آن می‌نشست و گریه می‌کرد."),
                    StoryParagraph("Then, one day, he found her letters from Léon and Rodolphe.", "بعد، یک روز، نامه‌هایش از لئون و رودولف را پیدا کرد."),
                    StoryParagraph("He learned the truth about her affairs, about her debts, about everything she had hidden from him.", "او حقیقت را درباره روابطش فهمید، درباره بدهی‌هایش، درباره هر چیزی که از او پنهان کرده بود."),
                    StoryParagraph("The discovery broke what was left of his heart.", "این کشف آنچه از قلبش باقی مانده بود را شکست."),
                    StoryParagraph("He stopped speaking, stopped eating, stopped living.", "او از صحبت کردن دست کشید، از خوردن، از زندگی کردن."),
                    StoryParagraph("He died a few months later, alone in his garden, holding a lock of Emma's hair.", "چند ماه بعد مرد، تنهای تنها در باغش، در حالی که قفلی از موی اِما در دستش بود."),
                    StoryParagraph("Their daughter Berthe was sent to live with a poor aunt.", "دخترشان برت را برای زندگی نزد خاله‌ای فقیر فرستادند."),
                    StoryParagraph("She grew up in poverty, forced to work in a cotton mill from a young age.", "او در فقر بزرگ شد و از سن کم مجبور شد در کارخانه پنبه کار کند."),
                    StoryParagraph("The beautiful, restless, dreaming Emma Bovary had left nothing behind but ruin.", "اِما بواری زیبا، بی‌قرار و رؤیاپرداز چیزی جز تباهی از خود باقی نگذاشته بود."),
                    StoryParagraph("She had wanted everything, and she had lost everything.", "او همه چیز را خواسته بود و همه چیز را از دست داده بود."),
                    StoryParagraph("She had dreamed of love, and she had found only betrayal.", "رویای عشق را در سر داشت و فقط خیانت یافته بود."),
                    StoryParagraph("She had dreamed of happiness, and she had found only despair.", "رویای خوشبختی را در سر داشت و فقط ناامیدی یافته بود."),
                    StoryParagraph("She had dreamed of meaning, and she had found only emptiness.", "رویای معنا را در سر داشت و فقط پوچی یافته بود."),
                    StoryParagraph("And in the end, that emptiness had consumed her.", "و در نهایت، آن پوچی بلعیدش."),
                    StoryParagraph("The end.", "پایان.")
                )
            )
        )
    )

    // ─────────────── ۳۸: بینوایان ───────────────
    private fun story38() = StoryContent(
        storyId = "int_les_miserables_int",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Prisoner", titlePersian = "زندانی",
                paragraphs = listOf(
                    StoryParagraph("Jean Valjean was a poor man who lived in a small village in the south of France.", "ژان والژان مرد فقیری بود که در دهکده‌ای کوچک در جنوب فرانسه زندگی می‌کرد."),
                    StoryParagraph("He was a pruner of trees, a simple laborer who worked long hours for very little money.", "او هرس‌کننده درختان بود، کارگری ساده که ساعت‌های طولانی برای پول خیلی کم کار می‌کرد."),
                    StoryParagraph("His parents had died when he was young, leaving him to care for his widowed sister and her seven children.", "والدینش وقتی جوان بود مرده بودند و او را برای مراقبت از خواهر بیوه‌اش و هفت فرزندش تنها گذاشته بودند."),
                    StoryParagraph("There was never enough food in the house.", "هیچ‌وقت به‌اندازه کافی غذا در خانه نبود."),
                    StoryParagraph("There was never enough wood for the fire.", "هیچ‌وقت به‌اندازه کافی چوب برای آتش نبود."),
                    StoryParagraph("The children cried from hunger every night, and Valjean could not bear to hear them.", "بچه‌ها هر شب از گرسنگی گریه می‌کردند و والژان نمی‌توانست تحمل کند صدایشان را بشنود."),
                    StoryParagraph("One cold winter evening, when the food had run out and the children were sobbing, Valjean did something desperate.", "یک عصر سرد زمستان، وقتی غذا تمام شده بود و بچه‌ها هق‌هق می‌کردند، والژان کاری از سر ناچاری کرد."),
                    StoryParagraph("He broke the window of a bakery and stole a single loaf of bread.", "او پنجره نانوایی را شکست و یک قرص نان دزدید."),
                    StoryParagraph("It was not greed that drove him; it was hunger, and love, and the desperation of a man watching children starve.", "طمع نبود که او را راند؛ گرسنگی بود، و عشق، و ناامیدی مردی که می‌دید بچه‌ها از گرسنگی می‌میرند."),
                    StoryParagraph("He was caught almost immediately, and arrested, and taken to court.", "تقریباً بلافاصله دستگیر شد و به دادگاه برده شد."),
                    StoryParagraph("The judge sentenced him to five years of hard labor in the galleys.", "قاضی او را به پنج سال کار سخت در کشتی‌های پارویی محکوم کرد."),
                    StoryParagraph("Valjean wept when he heard the sentence, because he knew that his sister and her children would surely die without him.", "والژان وقتی حکم را شنید گریه کرد، چون می‌دانست خواهرش و بچه‌هایش بدون او قطعاً می‌میرند."),
                    StoryParagraph("But the law did not care about such things, and he was taken away in chains.", "اما قانون به چنین چیزهایی اهمیت نمی‌داد و او را در زنجیر بردند."),
                    StoryParagraph("In the galleys, he tried to escape four times, and each attempt added years to his sentence.", "در کشتی‌های پارویی، چهار بار تلاش کرد فرار کند و هر تلاش سال‌هایی به محکومیتش اضافه کرد."),
                    StoryParagraph("The first attempt added three years; the second added five; the third and fourth added even more.", "تلاش اول سه سال اضافه کرد؛ دومی پنج سال؛ سومی و چهارمی بیشتر هم."),
                    StoryParagraph("What had begun as a five-year sentence became nineteen years of brutal labor.", "آنچه با حکم پنج سال شروع شده بود، به نوزده سال کار وحشیانه تبدیل شد."),
                    StoryParagraph("In those nineteen years, Valjean changed completely.", "در آن نوزده سال، والژان کاملاً عوض شد."),
                    StoryParagraph("He had entered prison as a gentle, loving, desperate man.", "او به‌عنوان مردی ملایم، عاشق و ناامید وارد زندان شده بود."),
                    StoryParagraph("He left it as a bitter, hardened, hateful man.", "به‌عنوان مردی تلخ، سخت و نفرت‌انگیز ترکش کرد."),
                    StoryParagraph("He had learned that the world was cruel, that justice was a lie, that kindness was weakness.", "او آموخته بود دنیا بی‌رحم است، عدالت دروغ است، مهربانی ضعف است."),
                    StoryParagraph("He had watched good men suffer and bad men prosper, and he had concluded that there was no God and no meaning.", "او دیده بود مردان خوب رنج می‌کشند و مردان بد رونق می‌گیرند و نتیجه گرفته بود خدایی نیست و معنایی نیست."),
                    StoryParagraph("By the time he was finally released, at the age of forty-six, he hated humanity with every fiber of his being.", "تا وقتی بالاخره آزاد شد، در سن چهل و شش سالگی، با هر ذره وجودش از بشریت متنفر بود."),
                    StoryParagraph("He was given a yellow passport that identified him as a former convict.", "پاسپورتی زرد به او دادند که او را به‌عنوان زندانی سابق معرفی می‌کرد."),
                    StoryParagraph("With this passport, no inn would take him in, no employer would hire him, no one would treat him as a human being.", "با این پاسپورت، هیچ مسافرخانه‌ای او را نمی‌پذیرفت، هیچ کارفرمایی استخدامش نمی‌کرد، هیچ‌کس مثل انسان با او رفتار نمی‌کرد."),
                    StoryParagraph("He was turned away from every door, chased from every town, treated like a wild animal.", "از هر دری رانده شد، از هر شهری تعقیب شد، مثل حیوان وحشی با او رفتار شد."),
                    StoryParagraph("Finally, in the town of Digne, a kind woman told him to try the house of the bishop.", "بالاخره، در شهر دین، زنی مهربان به او گفت خانه اسقف را امتحان کند."),
                    StoryParagraph("The bishop, whose name was Bienvenu Myriel, was a man of great kindness and humility.", "اسقف که نامش بیَنوِنو میریل بود، مردی با مهربانی و فروتنی بسیار بود."),
                    StoryParagraph("He lived simply, gave most of his income to the poor, and treated everyone with equal respect.", "او ساده زندگی می‌کرد، بیشتر درآمدش را به فقرا می‌داد و با همه با احترام برابر رفتار می‌کرد."),
                    StoryParagraph("When Valjean arrived at his door, exhausted and angry, the bishop welcomed him warmly.", "وقتی والژان خسته و خشمگین به درش رسید، اسقف گرم استقبالش کرد."),
                    StoryParagraph("He gave him food, a bed, and something that Valjean had almost forgotten: kindness.", "او به او غذا، تختی و چیزی داد که والژان تقریباً فراموش کرده بود: مهربانی."),
                    StoryParagraph("That night, Valjean could not sleep; the hatred inside him would not let him rest.", "آن شب، والژان نمی‌توانست بخوابد؛ نفرت درونش اجازه نمی‌داد آرام بگیرد."),
                    StoryParagraph("He got up in the darkness, and he stole the bishop's silver plates and candlesticks.", "در تاریکی بلند شد و بشقاب‌ها و شمعدان‌های نقره‌ای اسقف را دزدید."),
                    StoryParagraph("He fled into the night, but he was caught by the police before dawn.", "به شب فرار کرد، اما قبل از سپیده توسط پلیس دستگیر شد."),
                    StoryParagraph("They dragged him back to the bishop's house, expecting the bishop to accuse him.", "او را به خانه اسقف کشیدند، به انتظار اینکه اسقف متهمش کند."),
                    StoryParagraph("But the bishop did something extraordinary.", "اما اسقف کاری فوق‌العاده کرد."),
                    StoryParagraph("'My friend,' he said, 'you forgot to take the candlesticks as well. Here, take them.'", "گفت: «دوست من، یادت رفت شمعدان‌ها را هم ببری. بگیر، ببرشان.»"),
                    StoryParagraph("Then he turned to the police and said, 'This man is my guest. Please release him.'", "سپس به پلیس رو کرد و گفت: «این مرد مهمان من است. لطفاً آزادش کنید.»"),
                    StoryParagraph("The police, confused and angry, let Valjean go.", "پلیس، گیج و عصبانی، والژان را رها کرد."),
                    StoryParagraph("When they were alone, the bishop looked at Valjean with deep, sorrowful eyes.", "وقتی تنهای تنها شدند، اسقف با چشمانی عمیق و اندوهناک به والژان نگاه کرد."),
                    StoryParagraph("'Jean Valjean,' he said, 'you have promised me nothing, but I am giving you everything.'", "گفت: «ژان والژان، تو به من چیزی قول نداده‌ای، اما من همه چیز به تو می‌دهم.»"),
                    StoryParagraph("'I am buying your soul from hatred and giving it back to hope.'", "«روحت را از نفرت می‌خرم و به امید برمی‌گردانم.»"),
                    StoryParagraph("'Use this silver to become an honest man.'", "«از این نقره استفاده کن تا مرد صادقی شوی.»"),
                    StoryParagraph("'You belong no longer to evil, but to good.'", "«تو دیگر به شر تعلق نداری، به خیر تعلق داری.»"),
                    StoryParagraph("'I am saving your soul for God.'", "«روحت را برای خدا نجات می‌دهم.»"),
                    StoryParagraph("Valjean was struck to the heart.", "والژان به قلب زده شد."),
                    StoryParagraph("He had never heard anything like this before.", "او هرگز چیزی شبیه این نشنیده بود."),
                    StoryParagraph("He had expected hatred, and he had received love; he had expected punishment, and he had received redemption.", "انتظار نفرت داشت و عشق دریافت کرده بود؛ انتظار مجازات داشت و رستگاری دریافت کرده بود."),
                    StoryParagraph("He walked out of the bishop's house in a daze, and he sat down by the roadside and wept for hours.", "گیج از خانه اسقف بیرون رفت و کنار جاده نشست و ساعت‌ها گریه کرد."),
                    StoryParagraph("He thought about his life, his crimes, his hatred, his despair.", "به زندگی‌اش فکر کرد، به جنایاتش، به نفرتش، به ناامیدی‌اش."),
                    StoryParagraph("And something inside him cracked open, and light came flooding in.", "و چیزی در درونش شکافت و باز شد و نور به داخل سرازیر شد."),
                    StoryParagraph("When he stood up, he was not the same man who had sat down.", "وقتی بلند شد، همان مردی نبود که نشسته بود."),
                    StoryParagraph("He was a new man, reborn, forgiven, redeemed.", "او مردی جدید بود، دوباره متولد شده، بخشیده شده، رستگار شده."),
                    StoryParagraph("He tore up his yellow passport, and he vowed to live the rest of his life as a good and honest man.", "پاسپورت زردش را پاره کرد و قسم خورد بقیه عمرش را به‌عنوان مردی خوب و صادق زندگی کند."),
                    StoryParagraph("He did not know what the future would hold.", "نمی‌دانست آینده چه در بر دارد."),
                    StoryParagraph("He did not know the trials he would face, or the love he would find, or the sacrifices he would make.", "نمی‌دانست چه آزمون‌هایی در پیش است، یا عشقی که می‌یابد، یا فداکاری‌هایی که می‌کند."),
                    StoryParagraph("But he knew, for the first time in nineteen years, that he was free.", "اما برای اولین بار در نوزده سال می‌دانست که آزاد است."),
                    StoryParagraph("Truly free.", "واقعاً آزاد."),
                    StoryParagraph("And that was everything.", "و این همه چیز بود.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Mayor", titlePersian = "شهردار",
                paragraphs = listOf(
                    StoryParagraph("Valjean changed his name and his appearance, and he traveled far to the north, to a small town called Montreuil-sur-Mer.", "والژان نام و ظاهرش را عوض کرد و دور، به شمال، به شهر کوچکی به نام مونتروی-سور-مر سفر کرد."),
                    StoryParagraph("He arrived as an unknown man with no past and no connections, but he arrived with a fierce determination to become good.", "او به‌عنوان مردی ناشناخته بدون گذشته و بدون ارتباطات رسید، اما با عزمی سرسخت برای خوب شدن."),
                    StoryParagraph("He found work in a factory that made beads, and he worked harder than any man in the town.", "او در کارخانه‌ای که مهره می‌ساخت کار پیدا کرد و سخت‌تر از هر مردی در شهر کار کرد."),
                    StoryParagraph("He saved his money, he studied, he learned, and he began to think of new ways to improve the manufacturing process.", "پولش را ذخیره کرد، مطالعه کرد، یاد گرفت و شروع کرد به فکر کردن راه‌های جدید برای بهبود فرآیند تولید."),
                    StoryParagraph("One day, he invented a new method that made the beads stronger and cheaper to produce.", "یک روز، روش جدیدی اختراع کرد که مهره‌ها را قوی‌تر و ارزان‌تر می‌ساخت."),
                    StoryParagraph("The factory owners were so impressed that they made him a partner, and soon he was a wealthy man.", "صاحبان کارخانه آنقدر تحت تأثیر قرار گرفتند که شریکش کردند و به‌زودی مرد ثروتمندی شد."),
                    StoryParagraph("But he did not use his wealth for himself; he used it for others.", "اما ثروتش را برای خودش استفاده نکرد؛ برای دیگران استفاده کرد."),
                    StoryParagraph("He built a new hospital for the town, paid for by his own money.", "او بیمارستان جدیدی برای شهر ساخت که با پول خودش پرداخت می‌شد."),
                    StoryParagraph("He built schools where poor children could learn to read and write.", "او مدارسی ساخت که بچه‌های فقیر می‌توانستند خواندن و نوشتن یاد بگیرند."),
                    StoryParagraph("He helped the poor, the sick, and the elderly, always quietly, always generously.", "او به فقرا، بیماران و سالخوردگان کمک می‌کرد، همیشه بی‌صدا، همیشه سخاوتمندانه."),
                    StoryParagraph("His reputation grew, and the people of the town came to love and respect him.", "شهرتش رشد کرد و مردم شهر عاشقش شدند و به او احترام گذاشتند."),
                    StoryParagraph("Eventually, they asked him to become their mayor.", "در نهایت، از او خواستند شهردارشان شود."),
                    StoryParagraph("He accepted the position, and he ruled wisely, fairly, and with an unwavering commitment to justice.", "او این مقام را پذیرفت و عاقلانه، عادلانه و با تعهدی تزلزل‌ناپذیر به عدالت حکومت کرد."),
                    StoryParagraph("The town flourished under his leadership; it became a model of what a community could be when it was led by a good man.", "شهر تحت رهبری‌اش شکوفا شد؛ به نمونه‌ای از آنچه یک جامعه می‌تواند باشد وقتی توسط مرد خوبی رهبری می‌شود تبدیل شد."),
                    StoryParagraph("But one man in the town did not love him.", "اما یک مرد در شهر دوستش نداشت."),
                    StoryParagraph("That man was Inspector Javert, the chief of police.", "آن مرد بازرس ژاور، رئیس پلیس، بود."),
                    StoryParagraph("Javert was a tall, stern man with grey eyes and an unyielding sense of duty.", "ژاور مردی بلندقد و سختگیر با چشمان خاکستری و حس وظیفه‌ای تسلیم‌ناپذیر بود."),
                    StoryParagraph("He had been born in a prison, the son of a fortune-teller and a convict, and he had spent his entire life trying to prove that he was on the side of the law.", "او در زندانی به دنیا آمده بود، پسر یک فالگیر و یک زندانی، و تمام عمرش را صرف تلاش برای اثبات این کرده بود که در طرف قانون است."),
                    StoryParagraph("For Javert, the law was not merely a set of rules; it was the very structure of the universe.", "برای ژاور، قانون فقط مجموعه‌ای از قوانین نبود؛ ساختار خود جهان بود."),
                    StoryParagraph("The guilty must be punished; the innocent must be protected; there was no middle ground, no mercy, no exception.", "مجرم باید مجازات شود؛ بی‌گناه باید محافظت شود؛ زمین میانی نبود، نه رحمی، نه استثنایی."),
                    StoryParagraph("When Javert first saw the mayor, he felt a strange unease, a sense that he had seen this man somewhere before.", "وقتی ژاور اولین بار شهردار را دید، ناآرامی عجیبی حس کرد، حسی که این مرد را جایی قبلاً دیده است."),
                    StoryParagraph("The face was different, the manner was different, but something about the man's great strength and his strange, quiet humility stirred a memory in Javert's mind.", "صورت متفاوت بود، رفتار متفاوت بود، اما چیزی درباره قدرت بزرگ مرد و فروتنی عجیب و آرامش خاطره‌ای در ذهن ژاور تکان داد."),
                    StoryParagraph("He began to watch the mayor closely, looking for any sign, any clue, any mistake.", "او شروع کرد به تماشای دقیق شهردار، به دنبال هر نشانه‌ای، هر سرنخی، هر اشتباهی."),
                    StoryParagraph("Then, one day, an old convict named Champmathieu was arrested and put on trial.", "بعد، یک روز، زندانی سابقی به نام شانماتیو دستگیر و محاکمه شد."),
                    StoryParagraph("The authorities believed that this man was actually Jean Valjean, the former convict who had broken his parole.", "مقامات باور داشتند این مرد در واقع ژان والژان است، زندانی سابقی که آزادی مشروطش را شکسته بود."),
                    StoryParagraph("Champmathieu denied it, but no one believed him; he looked like Valjean, he had the same build, the same background, the same yellow passport.", "شانماتیو انکار کرد، اما کسی باورش نکرد؛ شبیه والژان بود، همان هیکل را داشت، همان پیشینه را، همان پاسپورت زرد را."),
                    StoryParagraph("The trial was set, and it seemed certain that Champmathieu would be sent to the galleys for life.", "محاکمه تعیین شد و قطعی به نظر می‌رسید که شانماتیو برای همیشه به کشتی‌های پارویی فرستاده شود."),
                    StoryParagraph("The mayor heard about the trial, and he realized with horror that an innocent man was about to be punished for his crimes.", "شهردار درباره محاکمه شنید و با وحشت فهمید مردی بی‌گناه در شرف مجازات شدن برای جنایات اوست."),
                    StoryParagraph("He could stay silent and remain safe, or he could confess and destroy himself.", "او می‌توانست سکوت کند و در امان بماند، یا می‌توانست اعتراف کند و خودش را نابود کند."),
                    StoryParagraph("For a long night, he wrestled with the decision.", "برای شبی طولانی، با تصمیم کشتی گرفت."),
                    StoryParagraph("He thought about Cosette, the young girl he had promised to protect, whose mother had died in his factory.", "به کوزت فکر کرد، دختر جوانی که قول داده بود محافظتش کند، که مادرش در کارخانه‌اش مرده بود."),
                    StoryParagraph("He thought about the town, which depended on him, which would suffer without his leadership.", "به شهر فکر کرد که به او وابسته بود، که بدون رهبری‌اش رنج می‌کشید."),
                    StoryParagraph("He thought about his own life, his own freedom, his own chance at redemption.", "به زندگی خودش فکر کرد، به آزادی خودش، به فرصت خودش برای رستگاری."),
                    StoryParagraph("But in the end, he could not let an innocent man suffer in his place.", "اما در نهایت، نمی‌توانست بگذارد مرد بی‌گناهی به جای او رنج بکشد."),
                    StoryParagraph("He traveled to the court in the middle of the night, and he stood before the judges, and he said the words that would destroy him.", "او در نیمه شب به دادگاه سفر کرد و پیش روی قضات ایستاد و کلماتی را گفت که نابودش می‌کرد."),
                    StoryParagraph("'I am Jean Valjean,' he said. 'Release this man; he is innocent.'", "گفت: «من ژان والژان هستم. این مرد را آزاد کنید؛ او بی‌گناه است.»"),
                    StoryParagraph("The courtroom erupted in chaos; no one could believe what they had heard.", "دادگاه در آشفتگی منفجر شد؛ هیچ‌کس نمی‌توانست باور کند چه شنیده است."),
                    StoryParagraph("But Valjean insisted, and he proved his identity, and Champmathieu was released.", "اما والژان اصرار کرد و هویتش را ثابت کرد و شانماتیو آزاد شد."),
                    StoryParagraph("Valjean was arrested again, and this time, there was no mercy.", "والژان دوباره دستگیر شد و این بار رحمی نبود."),
                    StoryParagraph("He was taken to prison, chained, and condemned to return to the galleys for life.", "او را به زندان بردند، زنجیر کردند و به بازگشت برای همیشه به کشتی‌های پارویی محکوم کردند."),
                    StoryParagraph("But before he was taken away, he made one last request.", "اما قبل از اینکه ببرندش، یک درخواست آخر کرد."),
                    StoryParagraph("He asked to see Cosette one more time.", "خواست یک بار آخر کوزت را ببیند."),
                    StoryParagraph("He had promised her mother that he would protect her, and he would not break that promise, even if it cost him everything.", "او به مادرش قول داده بود محافظتش می‌کند و آن قول را نمی‌شکست، حتی اگر همه چیز هزینه داشته باشد."),
                    StoryParagraph("That night, he escaped from prison.", "آن شب، از زندان فرار کرد."),
                    StoryParagraph("He went to the inn where Cosette lived, and he took her away.", "او به مسافرخانه‌ای رفت که کوزت زندگی می‌کرد و او را با خود برد."),
                    StoryParagraph("He had given up everything to save an innocent man, and now he was giving up everything to save an innocent child.", "او همه چیز را برای نجات مردی بی‌گناه داده بود و حالا همه چیز را برای نجات کودکی بی‌گناه می‌داد."),
                    StoryParagraph("And that, in the end, was what made him a good man.", "و این، در نهایت، چیزی بود که او را مردی خوب می‌ساخت.")
                )
            ),
            StoryChapter(
                number = 3, title = "Cosette", titlePersian = "کوزت",
                paragraphs = listOf(
                    StoryParagraph("Valjean found Cosette at the inn of the Thénardiers in the village of Montfermeil.", "والژان کوزت را در مسافرخانه تناردیه‌ها در دهکده مونفرمِی پیدا کرد."),
                    StoryParagraph("The inn was a miserable place, and the Thénardiers were miserable people.", "مسافرخانه جای رقت‌انگیزی بود و تناردیه‌ها افراد رقت‌انگیزی بودند."),
                    StoryParagraph("They were cruel, greedy, and utterly without conscience, and they treated Cosette like a slave.", "آن‌ها بی‌رحم، حریص و کاملاً بی‌وجدان بودند و با کوزت مثل برده رفتار می‌کردند."),
                    StoryParagraph("She swept the floors, she carried the water, she washed the dishes, she fetched the wood.", "او کف‌ها را جارو می‌کرد، آب می‌آورد، ظرف می‌شست، هیزم می‌آورد."),
                    StoryParagraph("She was always hungry, always cold, always covered in bruises and rags.", "همیشه گرسنه بود، همیشه سرد، همیشه پوشیده از کبودی و ژنده."),
                    StoryParagraph("She was eight years old, but she looked like a tiny, broken old woman.", "او هشت ساله بود اما شبیه پیرزنی کوچک و شکسته به نظر می‌رسید."),
                    StoryParagraph("When Valjean saw her, his heart broke.", "وقتی والژان دیدش، قلبش شکست."),
                    StoryParagraph("He remembered the bishop, who had saved him when he was at his lowest.", "اسقف را به یاد آورد، کسی که نجاتش داده بود وقتی در پایین‌ترین نقطه بود."),
                    StoryParagraph("He remembered how a single act of kindness had changed his entire life.", "به یاد آورد چطور یک عمل مهربانی واحد تمام زندگی‌اش را عوض کرده بود."),
                    StoryParagraph("And he decided that he would do the same for this child.", "و تصمیم گرفت همان را برای این کودک بکند."),
                    StoryParagraph("He paid the Thénardiers a great deal of money to take Cosette away.", "او به تناردیه‌ها پول زیادی داد تا کوزت را ببرند."),
                    StoryParagraph("They haggled and complained, but eventually they accepted, because the price was more than they could refuse.", "چانه زدند و شکایت کردند اما در نهایت پذیرفتند، چون قیمت بیشتر از آن بود که بتوانند رد کنند."),
                    StoryParagraph("Valjean took Cosette by the hand and led her out of the inn.", "والژان دست کوزت را گرفت و او را از مسافرخانه بیرون برد."),
                    StoryParagraph("She was terrified, because she did not understand what was happening, and she had never known anything but cruelty.", "او وحشت‌زده بود چون نمی‌فهمید چه اتفاقی می‌افتد و هرگز چیزی جز ظلم نشناخته بود."),
                    StoryParagraph("But Valjean spoke to her gently, and he gave her a doll, and he told her that she would never be hurt again.", "اما والژان ملایم با او صحبت کرد و عروسکی به او داد و گفت دیگر هرگز آسیب نخواهد دید."),
                    StoryParagraph("Cosette did not believe him at first, but slowly, over many months, she began to trust him.", "کوزت اول باورش نکرد، اما آهسته، در طول ماه‌های زیاد، شروع کرد به اعتماد کردن به او."),
                    StoryParagraph("Valjean took her to Paris, and he rented a small apartment where they could live quietly.", "والژان او را به پاریس برد و آپارتمانی کوچک اجاره کرد که بتوانند آرام زندگی کنند."),
                    StoryParagraph("He enrolled her in a convent school, where she was safe and cared for.", "او را در مدرسه صومعه‌ای ثبت‌نام کرد که در آن امن بود و از او مراقبت می‌شد."),
                    StoryParagraph("He visited her every day, and he brought her treats, and he read to her at night.", "او هر روز به دیدنش می‌رفت و برایش خوراکی می‌آورد و شب‌ها برایش می‌خواند."),
                    StoryParagraph("For the first time in her life, Cosette was happy.", "برای اولین بار در زندگی‌اش، کوزت خوشحال بود."),
                    StoryParagraph("For the first time in his life, Valjean felt what it was to love and be loved.", "برای اولین بار در زندگی‌اش، والژان حس کرد عشق ورزیدن و دوست داشته شدن چیست."),
                    StoryParagraph("He had never had children of his own, and he had lost his sister and her children years before, and Cosette filled a hole in his heart that he had thought would never be filled.", "او هرگز فرزندان خودش را نداشت و سال‌ها پیش خواهرش و بچه‌هایش را از دست داده بود و کوزت حفره‌ای در قلبش پر می‌کرد که فکر می‌کرد هرگز پر نمی‌شود."),
                    StoryParagraph("The years passed, and Cosette grew into a beautiful young woman.", "سال‌ها گذشتند و کوزت به زن جوان زیبایی تبدیل شد."),
                    StoryParagraph("She had golden hair, blue eyes, and a gentle, loving nature.", "موهای طلایی، چشمان آبی و طبیعتی ملایم و پر عشق داشت."),
                    StoryParagraph("Everyone who met her loved her immediately, and she loved everyone in return.", "هر کسی که ملاقاتش می‌کرد بلافاصله دوستش داشت و او هم در عوض همه را دوست داشت."),
                    StoryParagraph("But Valjean was always afraid, because he knew that Javert was still searching for him.", "اما والژان همیشه می‌ترسید، چون می‌دانست ژاور هنوز در جست‌وجویش است."),
                    StoryParagraph("And Javert, in fact, was closer than he knew.", "و ژاور، در واقع، نزدیک‌تر از آنچه می‌دانست بود."),
                    StoryParagraph("He had been tracking Valjean for years, following every lead, never giving up.", "سال‌ها والژان را تعقیب کرده بود، هر سرنخی را دنبال کرده بود، هرگز تسلیم نشده بود."),
                    StoryParagraph("Then, one day, when Cosette was in her late teens, Valjean decided that they had to move again.", "بعد، یک روز، وقتی کوزت در اواخر نوجوانی بود، والژان تصمیم گرفت باید دوباره نقل مکان کنند."),
                    StoryParagraph("He had seen Javert on the street, and he knew that the danger was too great.", "او ژاور را در خیابان دیده بود و می‌دانست خطر بیش از حد بزرگ است."),
                    StoryParagraph("He sold the apartment, and he moved Cosette to a small house on the Rue Plumet, on the edge of the city.", "او آپارتمان را فروخت و کوزت را به خانه کوچکی در خیابان پلومه، در حاشیه شهر برد."),
                    StoryParagraph("There, Cosette fell in love with a young man named Marius Pontmercy.", "آنجا، کوزت عاشق مرد جوانی به نام ماریوس پونتمرسی شد."),
                    StoryParagraph("Marius was a student, and a passionate idealist, and a member of a secret society of young revolutionaries.", "ماریوس دانشجویی، آرمان‌گرایی پرشور و عضوی از انجمن مخفی انقلابیون جوان بود."),
                    StoryParagraph("They met in the Luxembourg Gardens, where Cosette and Valjean went for walks every afternoon.", "آن‌ها در باغ لوکزامبورگ ملاقات کردند، جایی که کوزت و والژان هر بعدازظهر به پیاده‌روی می‌رفتند."),
                    StoryParagraph("Marius saw Cosette, and he fell in love with her at first sight.", "ماریوس کوزت را دید و در نگاه اول عاشقش شد."),
                    StoryParagraph("Cosette saw Marius, and she felt the same.", "کوزت ماریوس را دید و او هم همان حس را داشت."),
                    StoryParagraph("But Valjean was jealous of the young man, because he feared losing the only person he had ever loved.", "اما والژان از مرد جوان حسادت کرد، چون می‌ترسید تنها کسی که تا حالا دوست داشته بود را از دست بدهد."),
                    StoryParagraph("So he tried to keep them apart, and he tried to distract Cosette with other things.", "بنابراین تلاش کرد آن‌ها را از هم دور نگه دارد و تلاش کرد حواس کوزت را با چیزهای دیگر پرت کند."),
                    StoryParagraph("But love cannot be stopped by mere fatherly caution.", "اما عشق را نمی‌توان با احتیاط پدرانه صرف متوقف کرد."),
                    StoryParagraph("Marius and Cosette continued to meet in secret, and their love grew stronger every day.", "ماریوس و کوزت به ملاقات مخفیانه ادامه دادند و عشقشان هر روز قوی‌تر شد."),
                    StoryParagraph("Then, in June of 1832, the students rose up in rebellion against the government.", "سپس، در ژوئن ۱۸۳۲، دانشجویان بر علیه دولت شورش کردند."),
                    StoryParagraph("They built barricades in the streets of Paris, and they prepared to fight to the death for their ideals.", "آن‌ها در خیابان‌های پاریس سنگر ساختند و آماده شدند تا پای آرمان‌هایشان بجنگند تا مرگ."),
                    StoryParagraph("And Marius, despite his love for Cosette, could not stay away.", "و ماریوس، با وجود عشقش به کوزت، نمی‌توانست دور بماند."),
                    StoryParagraph("He went to the barricades, and he prepared to die for the cause he believed in.", "او به سنگرها رفت و آماده شد برای آرمانی که به آن باور داشت بمیرد."),
                    StoryParagraph("And Valjean, learning of this, went to the barricades too.", "و والژان که از این باخبر شد، او هم به سنگرها رفت."),
                    StoryParagraph("Not to fight, but to save the young man his daughter loved.", "نه برای جنگیدن، بلکه برای نجات مرد جوانی که دخترش دوست داشت."),
                    StoryParagraph("Because that is what love does, in the end.", "چون این چیزی است که عشق در نهایت می‌کند."),
                    StoryParagraph("It sacrifices itself for others.", "خودش را برای دیگران فدا می‌کند."),
                    StoryParagraph("And Valjean, above all else, had learned how to sacrifice.", "و والژان، بیش از هر چیز دیگری، یاد گرفته بود چطور فداکاری کند.")
                )
            ),
            StoryChapter(
                number = 4, title = "The Revolution", titlePersian = "انقلاب",
                paragraphs = listOf(
                    StoryParagraph("The June Rebellion of 1832 was a doomed uprising from the very beginning.", "شورش ژوئن ۱۸۳۲ از همان ابتدا قیامی محکوم به شکست بود."),
                    StoryParagraph("The students of Paris, inspired by revolutionary ideals, had taken to the streets to overthrow the monarchy.", "دانشجویان پاریس، الهام‌گرفته از آرمان‌های انقلابی، برای سرنگونی سلطنت به خیابان‌ها آمده بودند."),
                    StoryParagraph("They built barricades out of furniture, cobblestones, and broken carriages, and they prepared to fight the entire French army.", "آن‌ها از مبلمان، سنگفرش و کالسکه‌های شکسته سنگر ساختند و آماده شدند با تمام ارتش فرانسه بجنگند."),
                    StoryParagraph("They knew they would probably die, but they believed that their deaths would inspire future generations.", "می‌دانستند احتمالاً می‌میرند، اما باور داشتند مرگشان به نسل‌های آینده الهام می‌دهد."),
                    StoryParagraph("Marius was among them, fighting beside his friends with a rifle in his hand.", "ماریوس در میانشان بود و با تفنگی در دستش کنار دوستانش می‌جنگید."),
                    StoryParagraph("But he was distracted, because he had received a letter from Cosette, and he did not know if he would ever see her again.", "اما حواسش پرت بود چون نامه‌ای از کوزت دریافت کرده بود و نمی‌دانست آیا هرگز دوباره می‌بیندش."),
                    StoryParagraph("The fighting was fierce and bloody; many young men fell, one by one, as the army advanced.", "نبرد شدید و خونین بود؛ مردان جوان بسیاری افتادند، یکی‌یکی، همان‌طور که ارتش پیش می‌رفت."),
                    StoryParagraph("Marius fought bravely, but he was wounded in the chaos, and he collapsed behind the barricade.", "ماریوس شجاعانه جنگید اما در آشفتگی زخمی شد و پشت سنگر فرو افتاد."),
                    StoryParagraph("And then, in the smoke and blood and screaming, a hand reached down and grabbed him.", "و بعد، در دود و خون و جیغ، دستی به سمتش دراز شد و او را گرفت."),
                    StoryParagraph("It was Valjean.", "والژان بود."),
                    StoryParagraph("He had come to the barricade not to fight, but to find Marius and save him.", "او به سنگر آمده بود نه برای جنگیدن، بلکه برای پیدا کردن ماریوس و نجاتش."),
                    StoryParagraph("Because he knew that Cosette loved him, and he would not let her lose the man she loved.", "چون می‌دانست کوزت دوستش دارد و نمی‌گذاشت مردی که دوست دارد را از دست بدهد."),
                    StoryParagraph("He lifted Marius onto his shoulders and carried him through the chaos.", "او ماریوس را روی شانه‌هایش بلند کرد و از میان آشفتگی برد."),
                    StoryParagraph("He carried him into the sewers of Paris, into the darkness and filth and stench.", "او او را به فاضلاب‌های پاریس برد، به تاریکی و کثافت و بوی تعفن."),
                    StoryParagraph("For hours, he walked through the underground tunnels, carrying the unconscious young man on his back.", "ساعت‌ها در تونل‌های زیرزمینی راه رفت و مرد جوان بی‌هوش را روی پشتش حمل کرد."),
                    StoryParagraph("The mud was thick; the water was cold; the air was unbreathable.", "گل غلیظ بود؛ آب سرد؛ هوا غیرقابل تنفس."),
                    StoryParagraph("But he did not stop, because he had a promise to keep.", "اما متوقف نشد، چون قولی داشت که نگه دارد."),
                    StoryParagraph("When he finally emerged from the sewers, near the banks of the Seine, he was exhausted and barely alive.", "وقتی بالاخره از فاضلاب‌ها بیرون آمد، نزدیک کناره‌های سن، خسته و به‌سختی زنده بود."),
                    StoryParagraph("And waiting for him at the exit was Javert.", "و در خروجی منتظرش بود ژاور."),
                    StoryParagraph("The inspector had been searching for Valjean for years, and now, at last, he had found him.", "بازرس سال‌ها در جست‌وجوی والژان بود و حالا، بالاخره، پیدایش کرده بود."),
                    StoryParagraph("He drew his pistol and prepared to arrest the old convict.", "تپانچه‌اش را کشید و آماده شد زندانی سابق را دستگیر کند."),
                    StoryParagraph("But Valjean looked at him with tired, sad eyes, and he said, 'Javert, give me one hour.'", "اما والژان با چشمانی خسته و غمگین نگاهش کرد و گفت: «ژاور، یک ساعت به من بده.»"),
                    StoryParagraph("'One hour to take this boy to his family.'", "«یک ساعت تا این پسر را به خانواده‌اش برسانم.»"),
                    StoryParagraph("'Then I will come back and surrender to you.'", "«بعد برمی‌گردم و خودم را به تو تسلیم می‌کنم.»"),
                    StoryParagraph("Javert hesitated.", "ژاور تردید کرد."),
                    StoryParagraph("For years, Valjean had been his obsession, his mission, his only purpose.", "سال‌ها، والژان وسواسش، مأموریتش، تنها هدفش بود."),
                    StoryParagraph("But Valjean had also saved his life once, during the barricade, when Javert had been captured by the students and sentenced to death.", "اما والژان یک بار هم جانش را نجات داده بود، در طول سنگر، وقتی ژاور توسط دانشجویان دستگیر و به مرگ محکوم شده بود."),
                    StoryParagraph("Valjean had asked for the privilege of executing the spy, and instead, he had let Javert go free.", "والژان درخواست کرده بود افتخار اعدام جاسوس را داشته باشد و در عوض، گذاشته بود ژاور آزاد شود."),
                    StoryParagraph("That act of mercy had shattered something inside Javert.", "آن عمل رحم چیزی در درون ژاور را شکسته بود."),
                    StoryParagraph("Because Javert believed that criminals were evil and that mercy was weakness.", "چون ژاور باور داشت جنایتکاران شرورند و رحم ضعف است."),
                    StoryParagraph("But Valjean, a criminal, had shown him mercy; and now, Javert did not know what to believe anymore.", "اما والژان، یک جنایتکار، رحم نشانش داده بود؛ و حالا ژاور نمی‌دانست دیگر به چه باور کند."),
                    StoryParagraph("'Go,' he said quietly. 'Take the boy home. I will wait for you.'", "آرام گفت: «برو. پسر را به خانه ببر. منتظرت می‌مانم.»"),
                    StoryParagraph("Valjean carried Marius to his grandfather's house, and he left him there with the doctors.", "والژان ماریوس را به خانه پدربزرگش برد و او را با دکترها آنجا گذاشت."),
                    StoryParagraph("Then he walked back to Javert, as he had promised, ready to surrender himself.", "بعد همان‌طور که قول داده بود به سمت ژاور برگشت، آماده تسلیم شدن به او."),
                    StoryParagraph("But when he arrived, Javert was gone.", "اما وقتی رسید، ژاور رفته بود."),
                    StoryParagraph("The inspector had walked to the bridge over the Seine, and he had stood there for a long time, wrestling with himself.", "بازرس به پل روی سن رفته بود و مدت طولانی آنجا ایستاده بود و با خودش کشتی می‌گرفت."),
                    StoryParagraph("He could not arrest Valjean, because Valjean was a good man.", "او نمی‌توانست والژان را دستگیر کند چون والژان مرد خوبی بود."),
                    StoryParagraph("And he could not let him go, because the law was the law.", "و نمی‌توانست رهایش کند چون قانون قانون بود."),
                    StoryParagraph("He could not live with this contradiction, so he did the only thing that seemed possible.", "او نمی‌توانست با این تناقض زندگی کند، بنابراین تنها کاری که ممکن به نظر می‌رسید را انجام داد."),
                    StoryParagraph("He threw himself into the river and drowned.", "او خودش را در رودخانه انداخت و غرق شد."),
                    StoryParagraph("Javert, the man of absolute law, had been destroyed by a single act of mercy.", "ژاور، مرد قانون مطلق، با یک عمل رحم واحد نابود شده بود."),
                    StoryParagraph("Meanwhile, Marius recovered from his wounds, and he and Cosette were married in a quiet ceremony.", "در همین حال، ماریوس از زخم‌هایش بهبود یافت و او و کوزت در مراسمی آرام ازدواج کردند."),
                    StoryParagraph("Valjean gave them his fortune as a wedding gift, and he told Marius the truth about his past.", "والژان ثروتش را به‌عنوان هدیه عروسی به آن‌ها داد و حقیقت را درباره گذشته‌اش به ماریوس گفت."),
                    StoryParagraph("Marius was shocked at first, but in time, he came to understand and forgive.", "ماریوس اول شوکه شد، اما در زمانش، فهمید و بخشید."),
                    StoryParagraph("Valjean grew old and weak, and he lived alone in a small room, but Cosette visited him every day.", "والژان پیر و ضعیف شد و تنهای تنها در اتاقی کوچک زندگی می‌کرد، اما کوزت هر روز به دیدنش می‌رفت."),
                    StoryParagraph("She loved him like a father, and she never forgot what he had done for her.", "او او را مثل پدر دوست داشت و هرگز فراموش نکرد چه برایش کرده بود."),
                    StoryParagraph("When Valjean was dying, he called her to his bedside and held her hand.", "وقتی والژان در حال مرگ بود، او را کنار تختش صدا زد و دستش را گرفت."),
                    StoryParagraph("'Cosette,' he said softly, 'you have been the light of my life.'", "آرام گفت: «کوزت، تو نور زندگی من بوده‌ای.»"),
                    StoryParagraph("'Because of you, I learned what it means to love.'", "«به خاطر تو، یاد گرفتم عشق ورزیدن یعنی چه.»"),
                    StoryParagraph("'And because of you, I die a happy man.'", "«و به خاطر تو، مردی خوشحال می‌میرم.»"),
                    StoryParagraph("He closed his eyes, and he died with a peaceful smile on his face.", "چشمانش را بست و با لبخندی آرام روی صورتش مرد."),
                    StoryParagraph("Cosette wept, and Marius wept, and the world was darker for his passing.", "کوزت گریه کرد و ماریوس گریه کرد و دنیا با رفتنش تاریک‌تر شد."),
                    StoryParagraph("But his story did not end with his death.", "اما داستانش با مرگش تمام نشد."),
                    StoryParagraph("It lived on in Cosette, and in her children, and in the countless people whose lives he had touched.", "در کوزت زنده ماند و در فرزندانش و در افراد بی‌شماری که زندگی‌شان را لمس کرده بود."),
                    StoryParagraph("It lived on as a reminder that even the worst of men can become good.", "به‌عنوان یادآوری زنده ماند که حتی بدترین مردان می‌توانند خوب شوند."),
                    StoryParagraph("It lived on as a reminder that redemption is always possible.", "به‌عنوان یادآوری زنده ماند که رستگاری همیشه ممکن است."),
                    StoryParagraph("It lived on as a reminder that one act of kindness can change the world.", "به‌عنوان یادآوری زنده ماند که یک عمل مهربانی می‌تواند دنیا را عوض کند."),
                    StoryParagraph("And that, in the end, is what Les Misérables is truly about.", "و این، در نهایت، چیزی است که بینوایان واقعاً درباره‌اش است."),
                    StoryParagraph("Not the misery, but the hope.", "نه بدبختی، بلکه امید."),
                    StoryParagraph("Not the suffering, but the redemption.", "نه رنج، بلکه رستگاری."),
                    StoryParagraph("Not the darkness, but the light that overcomes it.", "نه تاریکی، بلکه نوری که بر آن غلبه می‌کند."),
                    StoryParagraph("The end.", "پایان.")
                )
            )
        )
    )

    // ─────────────── ۳۹: سه تفنگدار (نسخه ۲) ───────────────
    private fun story39() = StoryContent(
        storyId = "int_three_musketeers_v2",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Young Man", titlePersian = "مرد جوان",
                paragraphs = listOf(
                    StoryParagraph("D'Artagnan was a young man of eighteen, born in the poor but noble region of Gascony in the south of France.", "دارتانیان مرد جوانی هجده‌ساله بود، زاده منطقه فقیر اما اصیل گاسکونی در جنوب فرانسه."),
                    StoryParagraph("He had grown up in a small village where the men were known for their pride, their courage, and their quick tempers.", "او در دهکده‌ای کوچک بزرگ شده بود که مردانش به غرور، شجاعت و مزاج تندشان شناخته می‌شدند."),
                    StoryParagraph("His father had been a soldier in his youth, and he had raised his son on tales of glory and honor.", "پدرش در جوانی سرباز بوده بود و پسرش را با افسانه‌های افتخار و ناموس بزرگ کرده بود."),
                    StoryParagraph("When D'Artagnan turned eighteen, his father called him into the small room where he kept his most precious possessions.", "وقتی دارتانیان هجده ساله شد، پدرش او را به اتاق کوچکی که باارزش‌ترین دارایی‌هایش را در آن نگه می‌داشت صدا زد."),
                    StoryParagraph("'My son,' he said, 'you are now a man, and a man must make his own way in the world.'", "گفت: «پسرم، تو الان مردی، و مرد باید راه خودش را در دنیا بسازد.»"),
                    StoryParagraph("'I have nothing to give you but this old sword, this horse, and fifteen gold coins.'", "«چیزی برای دادن به تو ندارم جز این شمشیر قدیمی، این اسب و پانزده سکه طلا.»"),
                    StoryParagraph("'Go to Paris. Join the musketeers of the king. Make a name for yourself.'", "«به پاریس برو. به تفنگداران پادشاه بپیوند. نامی برای خودت بساز.»"),
                    StoryParagraph("'Never sell this sword, never accept an insult without challenge, and never forget that you are a Gascon.'", "«هرگز این شمشیر را نفروش، هرگز توهینی را بدون درخواست دوئل نپذیر، و هرگز فراموش نکن که گاسکونی هستی.»"),
                    StoryParagraph("D'Artagnan bowed and promised to obey, and he mounted his old yellow horse and rode away from his village.", "دارتانیان تعظیم کرد و قول اطاعت داد و سوار اسب زرد قدیمی‌اش شد و از دهکده‌اش دور شد."),
                    StoryParagraph("The road to Paris was long and full of adventures, but D'Artagnan was young and eager and unafraid.", "جاده پاریس طولانی و پر از ماجرا بود، اما دارتانیان جوان و مشتاق و نترس بود."),
                    StoryParagraph("At an inn in the town of Meung, he encountered a tall, dark man with a scar on his cheek.", "در مسافرخانه‌ای در شهر مونگ، با مردی بلندقد و تیره با زخمی روی گونه‌اش برخورد کرد."),
                    StoryParagraph("The man was laughing at D'Artagnan's yellow horse, and the young Gascon's temper flared immediately.", "آن مرد به اسب زرد دارتانیان می‌خندید و مزاج گاسکونی جوان فوراً شعله‌ور شد."),
                    StoryParagraph("He challenged the man to a duel, but before they could fight, the man's companions attacked D'Artagnan and beat him unconscious.", "او مرد را به دوئل دعوت کرد، اما قبل از اینکه بتوانند بجنگند، همراهان آن مرد به دارتانیان حمله کردند و بی‌هوشش کردند."),
                    StoryParagraph("When D'Artagnan woke, the man was gone, and his father's letter of introduction to the captain of the musketeers had been stolen.", "وقتی دارتانیان بیدار شد، مرد رفته بود و نامه معرفی پدرش به کاپیتان تفنگداران دزدیده شده بود."),
                    StoryParagraph("He swore that he would find the man and take his revenge.", "او قسم خورد آن مرد را پیدا کند و انتقامش را بگیرد."),
                    StoryParagraph("He rode on to Paris, arriving at last at the great city, which was larger and louder and more dangerous than anything he had ever seen.", "او به پاریس راند و بالاخره به شهر بزرگ رسید، که بزرگ‌تر و پرصداتر و خطرناک‌تر از هر چیزی بود که تا حالا دیده بود."),
                    StoryParagraph("He found the house of Monsieur de Tréville, the captain of the musketeers, and he was allowed to enter.", "او خانه موسیو دو ترِویل، کاپیتان تفنگداران، را پیدا کرد و اجازه ورود یافت."),
                    StoryParagraph("The courtyard was full of musketeers: tall, proud men in blue uniforms with swords at their sides.", "حیاط پر از تفنگداران بود: مردان بلندقد و مغرور در یونیفرم‌های آبی با شمشیر در کنارشان."),
                    StoryParagraph("D'Artagnan felt small and awkward among them, but he lifted his chin and walked with as much confidence as he could muster.", "دارتانیان در میانشان کوچک و دست‌وپاچلفتی حس کرد، اما چانه‌اش را بالا گرفت و با هر اعتماد به نفسی که می‌توانست جمع کند راه رفت."),
                    StoryParagraph("Tréville received him kindly and promised to help him join the musketeers.", "ترِویل مهربانانه پذیرفتش و قول داد کمکش کند به تفنگداران بپیوندد."),
                    StoryParagraph("But as D'Artagnan was leaving, he saw a familiar face in the crowd.", "اما وقتی دارتانیان می‌رفت، چهره آشنایی در جمعیت دید."),
                    StoryParagraph("It was the man with the scar, the man who had stolen his letter.", "مرد با زخم بود، مردی که نامه‌اش را دزدیده بود."),
                    StoryParagraph("D'Artagnan rushed forward without thinking, and in his haste, he knocked into three musketeers on the stairs.", "دارتانیان بدون فکر کردن به جلو هجوم برد و در عجله‌اش روی پله‌ها به سه تفنگدار برخورد کرد."),
                    StoryParagraph("One was Athos, a nobleman of quiet dignity; one was Porthos, a giant of a man with a loud laugh; one was Aramis, a young priest-in-training with a mysterious smile.", "یکی آتوس بود، نجیب‌زاده‌ای با وقار آرام؛ یکی پورتوس، غولی از مرد با خنده‌ای بلند؛ یکی آرامیس، کشیش جوان در حال آموزش با لبخندی مرموز."),
                    StoryParagraph("Each of them was offended by his clumsiness, and each of them demanded satisfaction in a duel.", "هر کدام از دست‌وپاچلفتی بودنش رنجیدند و هر کدام رضایت در دوئل خواستند."),
                    StoryParagraph("'At noon, near the Luxembourg,' Athos said coldly.", "آتوس سرد گفت: «ظهر، نزدیک لوکزامبورگ.»"),
                    StoryParagraph("'At one o'clock, behind the church,' said Porthos.", "پورتوس گفت: «ساعت یک، پشت کلیسا.»"),
                    StoryParagraph("'At two o'clock, by the river,' said Aramis quietly.", "آرامیس آرام گفت: «ساعت دو، کنار رودخانه.»"),
                    StoryParagraph("D'Artagnan accepted all three duels without hesitation.", "دارتانیان هر سه دوئل را بدون تردید پذیرفت."),
                    StoryParagraph("He knew he might die, but he also knew that he could not refuse.", "می‌دانست ممکن است بمیرد، اما می‌دانست نمی‌تواند رد کند."),
                    StoryParagraph("He was a Gascon, and a Gascon never backs down.", "او گاسکونی بود و گاسکونی هرگز عقب‌نشینی نمی‌کند."),
                    StoryParagraph("That afternoon, he went to the first duel, and then the second, and then the third.", "آن بعدازظهر، به دوئل اول رفت، بعد دومی، بعد سومی."),
                    StoryParagraph("But just as he was about to fight Athos, a company of the Cardinal's guards arrived, and they all turned their swords against the common enemy.", "اما درست وقتی داشت با آتوس می‌جنگید، گروهی از نگهبانان کاردینال رسیدند و همه شمشیرهایشان را علیه دشمن مشترک چرخاندند."),
                    StoryParagraph("The four men fought side by side against overwhelming odds, and by the end of the fight, they were brothers.", "چهار مرد کنار هم بر علیه شانس‌های طاقت‌فرسا جنگیدند و تا پایان نبرد، برادر بودند."),
                    StoryParagraph("'All for one, and one for all!' they shouted as they drove off the guards.", "آن‌ها همان‌طور که نگهبانان را می‌راندند فریاد زدند: «همه برای یکی، یکی برای همه!»"),
                    StoryParagraph("From that day forward, D'Artagnan was one of them.", "از آن روز به بعد، دارتانیان یکی از آن‌ها بود."),
                    StoryParagraph("He had found his place in the world.", "او جای خودش در دنیا را پیدا کرده بود."),
                    StoryParagraph("And his adventures had only just begun.", "و ماجراهایش تازه شروع شده بودند.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Queen's Diamonds", titlePersian = "الماس‌های ملکه",
                paragraphs = listOf(
                    StoryParagraph("The Queen of France, Anne of Austria, was in terrible danger.", "ملکه فرانسه، آن اتریش، در خطر وحشتناکی بود."),
                    StoryParagraph("She had made a terrible mistake, one that could destroy her reputation and even cost her her life.", "او اشتباه وحشتناکی کرده بود، اشتباهی که می‌توانست آبرویش را نابود کند و حتی زندگی‌اش را بگیرد."),
                    StoryParagraph("Years earlier, she had given a set of diamond studs to the Duke of Buckingham, an English nobleman who had once been her secret admirer.", "سال‌ها قبل، او مجموعه‌ای از دکمه‌های الماس را به دوک باکینگهام، نجیب‌زاده‌ای انگلیسی که زمانی تحسین‌کننده پنهانش بود داده بود."),
                    StoryParagraph("The studs had been a gift from the King, and giving them away was an act of treason, or at least an act of betrayal.", "دکمه‌ها هدیه‌ای از پادشاه بودند و دادنشان خیانت بود، یا حداقل خیانت به اعتماد."),
                    StoryParagraph("The Cardinal, Richelieu, had learned of this secret, and he intended to use it to destroy the Queen.", "کاردینال ریشلیو از این راز باخبر شده بود و قصد داشت از آن برای نابودی ملکه استفاده کند."),
                    StoryParagraph("He convinced the King to demand that the Queen wear the studs at an upcoming ball.", "او پادشاه را متقاعد کرد از ملکه بخواهد در بالماسکه پیش‌رو دکمه‌ها را بپوشد."),
                    StoryParagraph("The King, who was suspicious and jealous by nature, agreed.", "پادشاه، که به‌طور طبیعی مشکوک و حسود بود، موافقت کرد."),
                    StoryParagraph("When the Queen heard of this, she was filled with terror.", "وقتی ملکه از این باخبر شد، پر از وحشت شد."),
                    StoryParagraph("The studs were in England, in the possession of the Duke, hundreds of miles away, across a sea, and there was only one week until the ball.", "دکمه‌ها در انگلستان، در اختیار دوک، صدها مایل دور، آن‌طرف دریا بودند و تا بالماسکه فقط یک هفته بود."),
                    StoryParagraph("She sent for her most trusted lady-in-waiting, Constance Bonacieux, and asked for her help.", "او نزد معتمدترین ندیمه‌اش، کنستانس بوناسیو، فرستاد و کمکش را خواست."),
                    StoryParagraph("Constance knew exactly who to turn to: the young Gascon who had become a musketeer and who had already proven his courage.", "کنستانس دقیقاً می‌دانست به کی مراجعه کند: گاسکونی جوانی که تفنگدار شده بود و قبلاً شجاعتش را ثابت کرده بود."),
                    StoryParagraph("She went to D'Artagnan and told him everything.", "او به دارتانیان رفت و همه چیز را به او گفت."),
                    StoryParagraph("D'Artagnan listened carefully, and then he said simply, 'I will go to London.'", "دارتانیان با دقت گوش داد و بعد ساده گفت: «به لندن می‌روم.»"),
                    StoryParagraph("Constance looked at him with tears in her eyes.", "کنستانس با اشک در چشمانش نگاهش کرد."),
                    StoryParagraph("'You will be killed,' she whispered.", "نجوا کرد: «کشته می‌شوی.»"),
                    StoryParagraph("'Perhaps,' D'Artagnan said with a smile. 'But if I succeed, the Queen will be saved.'", "دارتانیان با لبخندی گفت: «شاید. اما اگر موفق شوم، ملکه نجات می‌یابد.»"),
                    StoryParagraph("He gathered his three friends, and he told them what he had to do.", "او سه دوستش را جمع کرد و به آن‌ها گفت باید چه کار کند."),
                    StoryParagraph("'We will go with you,' Athos said without hesitation.", "آتوس بدون تردید گفت: «با تو می‌آییم.»"),
                    StoryParagraph("'All of us,' Porthos added.", "پورتوس اضافه کرد: «همه‌مان.»"),
                    StoryParagraph("'The Queen's honor is our honor,' Aramis said quietly.", "آرامیس آرام گفت: «ناموس ملکه ناموس ماست.»"),
                    StoryParagraph("They set out that very night, riding hard toward the coast.", "آن‌ها همان شب راه افتادند، به‌سختی به سمت ساحل تاختند."),
                    StoryParagraph("But the Cardinal's spies were everywhere, and soon the four musketeers were being followed.", "اما جاسوسان کاردینال همه‌جا بودند و به‌زودی چهار تفنگدار تعقیب می‌شدند."),
                    StoryParagraph("The first attack came at a small bridge outside Paris.", "اولین حمله در پل کوچکی بیرون پاریس اتفاق افتاد."),
                    StoryParagraph("Eight of the Cardinal's guards blocked the road.", "هشت نگهبان کاردینال راه را بستند."),
                    StoryParagraph("'Go on!' Athos shouted. 'I will hold them here!'", "آتوس فریاد زد: «بروید! من اینجا نگهشان می‌دارم!»"),
                    StoryParagraph("D'Artagnan hesitated, but Athos pushed him forward.", "دارتانیان تردید کرد، اما آتوس هلش داد."),
                    StoryParagraph("'The mission is more important than my life!'", "«مأموریت از زندگی من مهم‌تر است!»"),
                    StoryParagraph("The three friends rode on while Athos fought alone.", "سه دوست سوار شدند و رفتند در حالی که آتوس تنها می‌جنگید."),
                    StoryParagraph("The second attack came at an inn where they stopped for food.", "دومین حمله در مسافرخانه‌ای که برای غذا توقف کردند اتفاق افتاد."),
                    StoryParagraph("Twelve guards surrounded them in the courtyard.", "دوازده نگهبان در حیاط احاطه‌شان کردند."),
                    StoryParagraph("'Go!' Porthos roared. 'I will handle these fools!'", "پورتوس غرید: «بروید! من این احمق‌ها را اداره می‌کنم!»"),
                    StoryParagraph("He threw a table through a window and jumped after it.", "میزی را از پنجره پرت کرد و به دنبالش پرید."),
                    StoryParagraph("The guards chased him, and the others escaped.", "نگهبانان دنبالش کردند و بقیه فرار کردند."),
                    StoryParagraph("The third attack came at a small village near the coast.", "سومین حمله در دهکده کوچکی نزدیک ساحل اتفاق افتاد."),
                    StoryParagraph("Twenty soldiers waited in the narrow street.", "بیست سرباز در خیابان باریک منتظر بودند."),
                    StoryParagraph("'This is where I leave you, my friend,' Aramis said sadly.", "آرامیس غمگین گفت: «اینجا جایی است که ترکت می‌کنم، دوستم.»"),
                    StoryParagraph("'I have always wanted to be a priest, but not today.'", "«همیشه می‌خواستم کشیش شوم، اما نه امروز.»"),
                    StoryParagraph("'Today I am a musketeer. Go. I will hold them.'", "«امروز تفنگدارم. برو. نگهشان می‌دارم.»"),
                    StoryParagraph("D'Artagnan rode on alone with tears in his eyes.", "دارتانیان با اشک در چشمانش تنها سوار شد و رفت."),
                    StoryParagraph("His three friends had sacrificed themselves for the Queen.", "سه دوستش خودشان را برای ملکه فدا کرده بودند."),
                    StoryParagraph("He reached Calais at sunset and found a ship ready to sail.", "او غروب به کاله رسید و کشتی‌ای آماده حرکت پیدا کرد."),
                    StoryParagraph("The crossing to England took only a few hours, but each moment felt like an eternity.", "عبور به انگلیس فقط چند ساعت طول کشید، اما هر لحظه مثل ابدیت بود."),
                    StoryParagraph("He rode hard to London and reached the Duke's palace at dawn.", "او به‌سختی به لندن تاخت و سپیده به قصر دوک رسید."),
                    StoryParagraph("The Duke of Buckingham was surprised to see him.", "دوک باکینگهام از دیدنش تعجب کرد."),
                    StoryParagraph("'I have come from the Queen of France,' D'Artagnan said.", "دارتانیان گفت: «از ملکه فرانسه آمده‌ام.»"),
                    StoryParagraph("'She needs the diamond studs back. Immediately.'", "«او دکمه‌های الماس را پس می‌خواهد. فوراً.»"),
                    StoryParagraph("Buckingham's face turned pale with understanding.", "صورت باکینگهام از درک رنگ‌پریده شد."),
                    StoryParagraph("'The Cardinal,' he whispered. 'He knows everything.'", "نجوا کرد: «کاردینال. او همه چیز را می‌داند.»"),
                    StoryParagraph("He opened a small box and looked inside.", "او جعبه کوچکی باز کرد و داخل را نگاه کرد."),
                    StoryParagraph("'Only ten studs are here,' he said with horror.", "با وحشت گفت: «فقط ده دکمه اینجاست.»"),
                    StoryParagraph("'I gave two to my jeweler for cleaning.'", "«دو تا را برای تمیز کردن به جواهرسازم دادم.»"),
                    StoryParagraph("'We must get them back before morning.'", "«باید تا صبح برگردانیمشان.»"),
                    StoryParagraph("Buckingham sent for his jeweler at once, and within hours, all twelve studs were in D'Artagnan's hands.", "باکینگهام فوراً جواهرسازش را خواست و در عرض چند ساعت، هر دوازده دکمه در دستان دارتانیان بودند."),
                    StoryParagraph("D'Artagnan rode back to Calais, crossed the sea, and reached Paris just in time.", "دارتانیان به کاله بازگشت، از دریا گذشت و دقیقاً به موقع به پاریس رسید."),
                    StoryParagraph("He arrived at the palace as the ball was beginning.", "او به قصر رسید همان‌طور که بالماسکه شروع می‌شد."),
                    StoryParagraph("The Queen was pale with fear and trembling.", "ملکه از ترس رنگ‌پریده و لرزان بود."),
                    StoryParagraph("D'Artagnan handed her the box with a low bow.", "دارتانیان با تعظیمی عمیق جعبه را به او داد."),
                    StoryParagraph("She opened it and saw all twelve studs shining inside.", "او بازش کرد و هر دوازده دکمه درخشان را دید."),
                    StoryParagraph("Tears of relief filled her eyes.", "اشک آسودگی چشمانش را پر کرد."),
                    StoryParagraph("'You have saved me,' she whispered. 'I will never forget.'", "نجوا کرد: «نجاتم دادی. هرگز فراموش نمی‌کنم.»"),
                    StoryParagraph("That night, the Queen wore the diamond studs proudly, and the King smiled, and the Cardinal fumed.", "آن شب، ملکه با افتخار دکمه‌های الماس را پوشید و پادشاه لبخند زد و کاردینال خشمگین شد."),
                    StoryParagraph("But the Cardinal did not give up. He never did.", "اما کاردینال تسلیم نشد. هرگز نمی‌شد."),
                    StoryParagraph("He began to plan an even darker revenge.", "او شروع کرد به نقشه کشیدن انتقامی حتی تاریک‌تر."),
                    StoryParagraph("And this time, he would use a beautiful woman to do it.", "و این بار، از زنی زیبا برای انجامش استفاده می‌کرد."),
                    StoryParagraph("Her name was Milady de Winter, and she was the most dangerous woman in France.", "نامش می‌لیدی دو وینتر بود و خطرناک‌ترین زن فرانسه بود.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Siege of La Rochelle", titlePersian = "محاصره لا روشل",
                paragraphs = listOf(
                    StoryParagraph("The King's army had surrounded the city of La Rochelle, the last stronghold of the Protestant rebels.", "ارتش پادشاه شهر لا روشل، آخرین سنگر شورشیان پروتستان، را محاصره کرده بود."),
                    StoryParagraph("It was a long, brutal siege, and the musketeers were camped outside the city walls with the rest of the army.", "محاصره‌ای طولانی و وحشیانه بود و تفنگداران همراه با بقیه ارتش بیرون دیوارهای شهر اردو زده بودند."),
                    StoryParagraph("The Cardinal had come to the siege in person, and he was using the opportunity to pursue his private schemes.", "کاردینال شخصاً به محاصره آمده بود و از این فرصت برای پیشبرد نقشه‌های خصوصی‌اش استفاده می‌کرد."),
                    StoryParagraph("His most dangerous scheme was a plan to assassinate the Duke of Buckingham.", "خطرناک‌ترین نقشه‌اش طرح ترور دوک باکینگهام بود."),
                    StoryParagraph("If Buckingham died, England would fall into chaos, and France would gain the advantage in the war.", "اگر باکینگهام می‌مرد، انگلیس در آشفتگی فرو می‌رفت و فرانسه در جنگ برتری می‌گرفت."),
                    StoryParagraph("To carry out this plan, the Cardinal relied on his most trusted agent: Milady de Winter.", "برای اجرای این نقشه، کاردینال به معتمدترین مأمورش تکیه کرد: می‌لیدی دو وینتر."),
                    StoryParagraph("Milady was beautiful, intelligent, and utterly without conscience.", "می‌لیدی زیبا، باهوش و کاملاً بی‌وجدان بود."),
                    StoryParagraph("She could lie more easily than she could breathe, and she could kill with a smile on her lips.", "دروغ گفتن برایش از نفس کشیدن آسان‌تر بود و می‌توانست با لبخندی روی لبش بکشد."),
                    StoryParagraph("She had been married once, to a nobleman, but she had committed terrible crimes, and she had been branded with the mark of a criminal.", "او یک بار ازدواج کرده بود، با نجیب‌زاده‌ای، اما جنایات وحشتناکی کرده بود و با داغ جنایتکار داغ خورده بود."),
                    StoryParagraph("Her husband, thinking she was dead, had never spoken of her again.", "شوهرش، که فکر می‌کرد مرده است، هرگز دوباره از او سخن نگفت."),
                    StoryParagraph("That husband was none other than Athos, the musketeer.", "آن شوهر کسی نبود جز آتوس، تفنگدار."),
                    StoryParagraph("Milady went to England, disguised, determined to kill Buckingham.", "می‌لیدی به انگلستان رفت، مبدل، مصمم به کشتن باکینگهام."),
                    StoryParagraph("She had once been the Duke's lover, and she used that old connection to get close to him.", "او زمانی معشوقه دوک بوده بود و از آن ارتباط قدیمی برای نزدیک شدن به او استفاده کرد."),
                    StoryParagraph("But D'Artagnan and his friends had learned of her plan, and they sent a warning to the Duke.", "اما دارتانیان و دوستانش از نقشه‌اش باخبر شده بودند و هشداری برای دوک فرستادند."),
                    StoryParagraph("The Duke was warned in time, and Milady was arrested.", "دوک به موقع هشدار داده شد و می‌لیدی دستگیر شد."),
                    StoryParagraph("She was imprisoned in the Tower of London, guarded day and night.", "او در برج لندن زندانی شد، شبانه‌روز محافظت‌شده."),
                    StoryParagraph("But Milady was not the kind of woman to stay imprisoned for long.", "اما می‌لیدی از آن زنانی نبود که مدت طولانی در زندان بماند."),
                    StoryParagraph("She seduced her young guard, convinced him to help her escape, and then killed him.", "او نگهبان جوانش را اغوا کرد، متقاعدش کرد کمکش کند فرار کند و بعد کشتش."),
                    StoryParagraph("She fled back to France, her heart burning with hatred for D'Artagnan.", "او به فرانسه فرار کرد، قلبش از نفرت از دارتانیان می‌سوخت."),
                    StoryParagraph("She had loved him once, or at least pretended to, and he had rejected her.", "او یک بار دوستش داشته بود، یا حداقل تظاهر کرده بود، و او رهایش کرده بود."),
                    StoryParagraph("Now she wanted revenge, and she would not rest until she had destroyed him and everyone he loved.", "حالا انتقام می‌خواست و تا وقتی او و هر کسی که دوست داشت را نابود نکند آرام نمی‌گرفت."),
                    StoryParagraph("Her first target was Constance Bonacieux, the woman D'Artagnan loved.", "اولین هدفش کنستانس بوناسیو بود، زنی که دارتانیان دوست داشت."),
                    StoryParagraph("She poisoned Constance slowly, through a trusted servant, and Constance fell desperately ill.", "او کنستانس را آرام‌آرام از طریق خدمتکاری قابل اعتماد مسموم کرد و کنستانس به‌شدت مریض شد."),
                    StoryParagraph("D'Artagnan rushed to her side, but it was too late.", "دارتانیان کنارش دوید، اما خیلی دیر شده بود."),
                    StoryParagraph("Constance died in his arms, and D'Artagnan's heart was shattered.", "کنستانس در آغوشش مرد و قلب دارتانیان خرد شد."),
                    StoryParagraph("He swore that he would hunt Milady down and bring her to justice.", "او قسم خورد می‌لیدی را شکار کند و به عدالت بسپارد."),
                    StoryParagraph("The four musketeers began their pursuit, following her trail across France.", "چهار تفنگدار شروع کردند به تعقیبش، ردش را در سراسر فرانسه دنبال کردند."),
                    StoryParagraph("They found her hiding in a convent, disguised as a nun.", "آن‌ها او را در صومعه‌ای پنهان پیدا کردند، مبدل به راهبه."),
                    StoryParagraph("But Milady had one more trick up her sleeve.", "اما می‌لیدی یک حقه آخر داشت."),
                    StoryParagraph("She sent a letter to the Cardinal, revealing that D'Artagnan had been protecting the Queen against his orders.", "او نامه‌ای به کاردینال فرستاد و فاش کرد دارتانیان برخلاف دستوراتش از ملکه محافظت می‌کرد."),
                    StoryParagraph("The Cardinal, furious, ordered D'Artagnan's arrest.", "کاردینال خشمگین دستور دستگیری دارتانیان را داد."),
                    StoryParagraph("But when the guards came to arrest him, D'Artagnan presented the Cardinal with a document of his own.", "اما وقتی نگهبانان برای دستگیری‌اش آمدند، دارتانیان سندی از خودش به کاردینال ارائه داد."),
                    StoryParagraph("It was a letter of pardon, signed by the King himself, granting D'Artagnan and his friends the right to act as they saw fit.", "نامه‌ای عفو بود، امضاشده توسط خود پادشاه، که به دارتانیان و دوستانش حق می‌داد هر طور که مناسب می‌دانند عمل کنند."),
                    StoryParagraph("The Cardinal was defeated, and D'Artagnan was free.", "کاردینال شکست خورد و دارتانیان آزاد شد."),
                    StoryParagraph("But Milady was still out there, and she would not stop until she was stopped.", "اما می‌لیدی هنوز آن بیرون بود و تا وقتی متوقف نشود متوقف نمی‌شد."),
                    StoryParagraph("The final confrontation was coming.", "رویارویی نهایی در راه بود.")
                )
            ),
            StoryChapter(
                number = 4, title = "The End of Milady", titlePersian = "پایان می‌لیدی",
                paragraphs = listOf(
                    StoryParagraph("The musketeers tracked Milady to a small village in the north of France.", "تفنگداران می‌لیدی را تا دهکده‌ای کوچک در شمال فرانسه دنبال کردند."),
                    StoryParagraph("She had taken refuge in a house by the river, and she was preparing to flee to England.", "او در خانه‌ای کنار رودخانه پناه گرفته بود و آماده می‌شد به انگلیس فرار کند."),
                    StoryParagraph("But she had run out of time.", "اما زمانش تمام شده بود."),
                    StoryParagraph("The four friends surrounded the house at night, blocking every exit.", "چهار دوست شب خانه را محاصره کردند و هر خروجی را بستند."),
                    StoryParagraph("Athos entered alone, sword in hand, and found Milady in the main room.", "آتوس تنها وارد شد، شمشیر در دست، و می‌لیدی را در اتاق اصلی یافت."),
                    StoryParagraph("When she saw him, her face went white, because she recognized him immediately.", "وقتی دیدش، صورتش سفید شد، چون فوراً شناختش."),
                    StoryParagraph("'You!' she whispered. 'It cannot be you!'", "نجوا کرد: «تو! نمی‌تواند تو باشی!»"),
                    StoryParagraph("'Yes, my dear,' Athos said coldly. 'It is me. Your husband, whom you thought was dead.'", "آتوس سرد گفت: «بله، عزیزم. من هستم. شوهرت، که فکر می‌کردی مرده است.»"),
                    StoryParagraph("Milady tried to run, but Porthos and Aramis blocked her path.", "می‌لیدی تلاش کرد فرار کند، اما پورتوس و آرامیس راهش را بستند."),
                    StoryParagraph("D'Artagnan stepped forward and looked at her with eyes full of grief and anger.", "دارتانیان جلو آمد و با چشمانی پر از اندوه و خشم نگاهش کرد."),
                    StoryParagraph("'You killed Constance,' he said quietly. 'You killed many others.'", "آرام گفت: «کنستانس را کشتی. بسیاری دیگر را هم کشتی.»"),
                    StoryParagraph("'You have committed crimes that cannot be forgiven.'", "«جنایاتی کرده‌ای که نمی‌توانند بخشیده شوند.»"),
                    StoryParagraph("Milady laughed, a cold, terrible laugh.", "می‌لیدی خندید، خنده‌ای سرد و هولناک."),
                    StoryParagraph("'You think you can judge me?' she said. 'You, who are no better than I am?'", "گفت: «فکر می‌کنی می‌توانی قضاوتم کنی؟ تو، که از من بهتر نیستی؟»"),
                    StoryParagraph("'You have killed, you have lied, you have betrayed.'", "«کشته‌ای، دروغ گفته‌ای، خیانت کرده‌ای.»"),
                    StoryParagraph("'We are the same.'", "«ما یکی هستیم.»"),
                    StoryParagraph("'No,' Athos said. 'We fight for honor. You fight only for yourself.'", "آتوس گفت: «نه. ما برای ناموس می‌جنگیم. تو فقط برای خودت می‌جنگی.»"),
                    StoryParagraph("They put her on trial there, in the house, with an old executioner who had been summoned from a nearby town.", "آن‌ها همان‌جا، در خانه، محاکمه‌اش کردند، با جلادی پیر که از شهر نزدیکی احضار شده بود."),
                    StoryParagraph("The executioner was a man who had known Milady years before, when she had committed her first crimes.", "جلاد مردی بود که سال‌ها قبل می‌لیدی را می‌شناخت، وقتی اولین جنایاتش را کرده بود."),
                    StoryParagraph("He had branded her with the fleur-de-lis, the mark of the criminal, and she had ruined his life in revenge.", "او با گل زنبق، علامت جنایتکار، داغش کرده بود و او در انتقام زندگی‌اش را نابود کرده بود."),
                    StoryParagraph("Now, at last, he would have his justice.", "حالا، بالاخره، عدالتش را می‌گرفت."),
                    StoryParagraph("The musketeers listed Milady's crimes: murder, poisoning, theft, betrayal, and countless others.", "تفنگداران جنایات می‌لیدی را برشمردند: قتل، مسمومیت، دزدی، خیانت و بی‌شمار دیگری."),
                    StoryParagraph("They spoke of Constance Bonacieux, who had died in D'Artagnan's arms.", "از کنستانس بوناسیو گفتند، که در آغوش دارتانیان مرده بود."),
                    StoryParagraph("They spoke of the Duke of Buckingham's near-assassination.", "از تلاش نزدیک به ترور دوک باکینگهام گفتند."),
                    StoryParagraph("They spoke of the many innocent people she had destroyed over the years.", "از افراد بی‌گناه بسیاری گفتند که در طول سال‌ها نابود کرده بود."),
                    StoryParagraph("Milady listened in silence, her face pale and still, her eyes burning with hatred.", "می‌لیدی در سکوت گوش داد، صورتش رنگ‌پریده و ساکن، چشمانش از نفرت می‌سوخت."),
                    StoryParagraph("She did not beg, she did not weep, she did not apologize.", "التماس نکرد، گریه نکرد، عذرخواهی نکرد."),
                    StoryParagraph("She only stared at them with contempt, as if they were insects beneath her notice.", "فقط با تحقیر به آن‌ها خیره شد، گویی حشراتی هستند پایین‌تر از توجهش."),
                    StoryParagraph("'You will all die,' she said quietly. 'Perhaps not today, perhaps not tomorrow, but eventually, you will all die, and I will be waiting for you in hell.'", "آرام گفت: «همه‌تان می‌میرید. شاید نه امروز، شاید نه فردا، اما در نهایت، همه‌تان می‌میرید و من در جهنم منتظرتان هستم.»"),
                    StoryParagraph("Athos bowed his head, and then he nodded to the executioner.", "آتوس سرش را خم کرد و بعد به جلاد سر تکان داد."),
                    StoryParagraph("The executioner took Milady by the arm and led her to the riverbank.", "جلاد می‌لیدی را از بازو گرفت و به کنار رودخانه برد."),
                    StoryParagraph("The moon was full, and the water was dark and cold.", "ماه کامل بود و آب تاریک و سرد."),
                    StoryParagraph("Milady did not resist; she stood there in the moonlight, beautiful and terrible, and she stared at the musketeers with defiance.", "می‌لیدی مقاومت نکرد؛ در نور ماه آنجا ایستاد، زیبا و هولناک، و با سرکشی به تفنگداران خیره شد."),
                    StoryParagraph("'I curse you all,' she said. 'I curse you and your children and your children's children.'", "گفت: «همه‌تان را نفرین می‌کنم. شما و فرزندانتان و فرزندان فرزندانتان را نفرین می‌کنم.»"),
                    StoryParagraph("The executioner raised his sword, and the moonlight flashed on the blade.", "جلاد شمشیرش را بالا برد و نور ماه روی تیغه برق زد."),
                    StoryParagraph("There was a single, terrible moment of silence, and then it was over.", "لحظه‌ای واحد و هولناک از سکوت بود و بعد تمام شد."),
                    StoryParagraph("Milady's body was thrown into the river, and the water closed over her, and she was gone.", "جسد می‌لیدی در رودخانه انداخته شد و آب رویش بسته شد و او رفته بود."),
                    StoryParagraph("The four musketeers stood on the riverbank in silence, watching the dark water flow past.", "چهار تفنگدار در سکوت کنار رودخانه ایستادند و تماشا کردند آب تاریک می‌گذرد."),
                    StoryParagraph("They had done what had to be done, but none of them felt any satisfaction.", "آن‌ها کاری که باید می‌کردند را کرده بودند، اما هیچ‌کدام هیچ رضایتی حس نکردند."),
                    StoryParagraph("They had killed a woman, and though she was a monster, she had also been human.", "آن‌ها زنی را کشته بودند و هرچند هیولا بود، او هم انسان بود."),
                    StoryParagraph("'Let us go home,' Athos said at last, and they mounted their horses and rode away.", "آتوس بالاخره گفت: «بیایید به خانه برویم،» و آن‌ها اسب‌هایشان را سوار شدند و رفتند."),
                    StoryParagraph("The Cardinal was furious when he learned of Milady's death, but he could do nothing.", "کاردینال وقتی از مرگ می‌لیدی باخبر شد خشمگین شد، اما نمی‌توانست کاری کند."),
                    StoryParagraph("D'Artagnan had proof of his crimes, and the King himself had pardoned the musketeers.", "دارتانیان مدرکی از جنایاتش داشت و خود پادشاه تفنگداران را بخشیده بود."),
                    StoryParagraph("So the Cardinal was forced to leave them alone, and D'Artagnan was promoted to the rank of lieutenant.", "بنابراین کاردینال مجبور شد آن‌ها را تنها بگذارد و دارتانیان به درجه ستوان ترفیع یافت."),
                    StoryParagraph("His three friends were honored as well, and the four of them became the most famous musketeers in all of France.", "سه دوستش هم مورد تجلیل قرار گرفتند و چهار نفرشان معروف‌ترین تفنگداران تمام فرانسه شدند."),
                    StoryParagraph("They continued to serve the King and the Queen, and they continued to have adventures.", "آن‌ها به خدمت پادشاه و ملکه ادامه دادند و به ماجراجویی ادامه دادند."),
                    StoryParagraph("They fought for honor, for friendship, and for each other.", "آن‌ها برای ناموس، برای دوستی و برای همدیگر جنگیدند."),
                    StoryParagraph("'All for one, and one for all!' remained their motto until the end of their days.", "«همه برای یکی، و یکی برای همه!» تا پایان روزگارشان شعارشان ماند."),
                    StoryParagraph("And when they finally grew old and died, their story was told and retold for generations.", "و وقتی بالاخره پیر شدند و مردند، داستانشان برای نسل‌ها گفته و بازگو شد."),
                    StoryParagraph("The story of four friends who had faced danger and death together.", "داستان چهار دوستی که با هم با خطر و مرگ روبرو شده بودند."),
                    StoryParagraph("The story of loyalty and courage and love.", "داستان وفاداری و شجاعت و عشق."),
                    StoryParagraph("The story of the three musketeers.", "داستان سه تفنگدار."),
                    StoryParagraph("And the young Gascon who became one of them.", "و گاسکونی جوانی که یکی از آن‌ها شد."),
                    StoryParagraph("The end.", "پایان."),
                    StoryParagraph("But their story will never truly end.", "اما داستانشان هرگز واقعاً تمام نخواهد شد."),
                    StoryParagraph("As long as men fight for honor and friendship, it will go on.", "تا وقتی مردانی برای ناموس و دوستی می‌جنگند، ادامه خواهد داشت."),
                    StoryParagraph("All for one, and one for all.", "همه برای یکی، و یکی برای همه.")
                )
            )
        )
    )
}